/* BEGIN GENERATED OPERATIONS MODULE */
/* Evidence-backed local operations. This module never contacts a shop or sends messages. */
window.CommerceOps=({api,esc,money,toast,repaint,getCostBase,isActive})=>{
  const state={tab:'alerts',demo:false,result:null,busy:false,error:'',kind:'order',form:{platform:'ozon',market:'RU',fulfillment:'unknown',store_id:'',warehouse:'',sku:'',source_ref:'',observed_at:'',order_id:'',quantity:'',status:'',ship_by:'',available:'',sold_units:'',window_days:'',lead_time_days:'',safety_days:'',pack_size:'',inbound_units:'',inbound_due_at:''},rules:null,pending:null,revision:0,comparison:null,comparisonError:'',comparisonBusy:false,scenario:{inventory_state:'unknown',target_contribution:''},plans:[{name:'方案 A',price:'',merchant_discount:'',ad_cost_per_unit:'',affiliate_rate:''},{name:'方案 B',price:'',merchant_discount:'',ad_cost_per_unit:'',affiliate_rate:''}]};
  const statuses={active:'待查看',acknowledged:'已阅 · 未确认处理',resolved:'已由后续记录关闭',suspended:'数据陈旧 · 已挂起'};
  const clock=s=>s?new Date(s).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'}):'未提供';
  const download=(body,name,type='application/json;charset=utf-8')=>{const url=URL.createObjectURL(new Blob([body],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000)};
  const field=(key,label,type='text',extra='')=>window.CommerceUI.field(label,window.CommerceUI.input({id:'ops-'+key,'data-ops-field':key,type,value:state.form[key],...window.CommerceUI.legacyAttributes(extra)}));
  const stockFields=[['available','当前可售库存'],['sold_units','观察期销量'],['window_days','观察天数'],['lead_time_days','到货交期（天）'],['safety_days','安全库存（天）'],['pack_size','每箱件数'],['inbound_units','确认在途数量（没有则填 0）']];
  async function load(){
    const demo=state.demo;state.busy=true;state.error='';
    try{const result=await api('commerce_ops_list',{demo});if(demo===state.demo){state.result=result;state.rules={...result.rules}}}
    catch(error){if(demo===state.demo)state.error='读取提醒失败：'+error.message}
    finally{if(demo===state.demo){state.busy=false;if(isActive())repaint()}}
  }
  function alerts(){
    const result=state.result;
    return `<div class="ops-toolbar"><label class="field"><span>资料范围</span><select id="ops-scope"><option value="manual" ${!state.demo?'selected':''}>手工资料 · 未连接平台</option><option value="demo" ${state.demo?'selected':''}>演示资料</option></select></label><button data-ops-action="refresh">刷新提醒</button><button data-ops-action="demo">载入演示订单与库存</button><button data-ops-action="export">导出提醒与来源证据</button></div>${state.error?`<div class="alert error" role="alert">${esc(state.error)}</div>`:''}${!result?'<p class="empty">读取本地提醒中…</p>':`<div class="ops-summary"><div><span>待查看</span><strong>${result.alerts.filter(a=>a.status==='active').length}</strong></div><div><span>已阅</span><strong>${result.alerts.filter(a=>a.status==='acknowledged').length}</strong></div><div><span>已挂起</span><strong>${result.alerts.filter(a=>a.status==='suspended').length}</strong></div></div><p class="muted">后台时钟：${result.connection.server_timer==='running'?'运行中，每 60 秒复核已存资料':'尚未启动'} · ${result.observation_count} 条最新记录。已阅不代表已经发货或补货。</p><section class="card"><h2>出单、履约与库存提醒</h2>${result.alerts.length?result.alerts.map(a=>`<article class="ops-alert ${a.status==='suspended'?'ops-muted':''}"><div class="ops-alert-head"><strong>${esc(a.title)}</strong><span class="badge ${a.severity==='P0'?'':'blue'}">${a.severity}</span><span class="badge gray">${esc(statuses[a.status])}</span></div><p>${esc(a.detail)}</p><p class="muted">${esc(a.platform)} · ${esc(a.store_id)} · ${esc(a.market)} · 仓库 ${esc(a.warehouse)} · SKU ${esc(a.sku)}${a.order_id?' · 订单 '+esc(a.order_id):''}<br>观察时间：${esc(clock(a.observed_at))} · ${a.source==='synthetic'?'演示数据':'手工资料，未独立核实'}</p><details><summary>查看来源与规则</summary><p class="muted">来源：${esc(a.source_ref)}<br>记录 SHA-256：${esc(a.source_sha256)}<br>数据有效期 ${a.rules.max_age_minutes} 分钟；发货预警提前 ${a.rules.dispatch_warning_hours} 小时。提醒 ID：${esc(a.id)}</p></details>${a.status==='active'?`<button data-ops-action="ack" data-id="${esc(a.id)}">标为已阅</button>`:''}</article>`).join(''):'<div class="empty">尚无提醒。没有导入数据时，不代表店铺没有订单或库存正常。</div>'}</section>${result.stock_plans.length?`<section class="card"><h2>补货测算依据</h2>${result.stock_plans.map(x=>`<div class="ops-alert"><strong>${esc(x.store_id)} / ${esc(x.warehouse)} / ${esc(x.sku)}</strong><p>${x.plan.status==='CALCULATED'?`日均 ${x.plan.velocity} 件；记录时覆盖 ${x.plan.current_cover} 天；可扣减在途 ${x.plan.eligible_inbound} 件；整箱建议 ${x.plan.suggested_qty} 件。`:'数据不足，补货数量保持未知。'}</p><p class="muted">${esc(x.plan.inbound_note||'在途为显式填写的零，按输入销量窗口外推。')} 来源时间 ${esc(clock(x.observed_at))}。测算草稿，不会下采购单。</p></div>`).join('')}</section>`:''}`}${recordForm()}${rulesForm()}`;
  }
  function recordForm(){return `<section class="card"><h2>核对并记录${state.kind==='order'?'订单':'库存'}</h2><p class="muted">从卖家后台或导出文件核对后填写。保存只更新本地提醒，来源记录与哈希会保留。当前保存到${state.demo?'演示资料':'手工资料'}。</p><div class="pills"><button data-ops-kind="order" class="pill ${state.kind==='order'?'active':''}">记录订单</button><button data-ops-kind="stock" class="pill ${state.kind==='stock'?'active':''}">记录库存</button></div><form id="ops-record-form" novalidate><div class="analysis-fields">${field('store_id','店铺标识 / 别名')}${field('warehouse','库存 / 发货仓库标识')}${field('market','国家站点')}${field('platform','平台标识（如 ozon）')}<label class="field"><span>履约方式</span><select id="ops-fulfillment" data-ops-field="fulfillment">${[['unknown','待确认'],['FBO','FBO'],['FBS','FBS'],['realFBS','realFBS'],['other','其它平台方式']].map(([k,v])=>`<option value="${k}" ${state.form.fulfillment===k?'selected':''}>${v}</option>`).join('')}</select></label>${field('sku','SKU')}${field('observed_at','本次实际核对时间（带时区）')}${field('source_ref','来源链接 / 文件名与行号 / 截图索引')}${state.kind==='order'?`${field('order_id','订单 / 发货单号')}${field('quantity','该 SKU 数量','number','min="1" step="1"')}<label class="field"><span>核对到的订单状态</span><select id="ops-status" data-ops-field="status"><option value="">请选择</option>${[['paid','已支付'],['awaiting_packaging','待备货'],['awaiting_dispatch','待发货'],['shipped','已发货'],['cancelled','已取消'],['completed','已完成']].map(([k,v])=>`<option value="${k}" ${state.form.status===k?'selected':''}>${v}</option>`).join('')}</select></label>${field('ship_by','来源中的发货截止时间（未知可留空）')}`:`${stockFields.map(([key,label])=>field(key,label,'number','min="0" step="1"')).join('')}${field('inbound_due_at','在途预计到达时间（有在途时填写，带时区）')}`}</div><div class="form-actions"><button type="submit" class="primary">保存并检查提醒</button><button type="button" data-ops-action="now">使用当前核对时间</button></div><p class="muted" data-ui-help>空白库存参数保持未知；没有在途请明确填 0。历史记录只留档，不覆盖较新的状态。</p></form><details class="knowledge-directory"><summary>批量接入与数据模板</summary><p class="muted" data-ui-help>可下载单条标准模板，核对后导入 JSON 记录或记录数组。模板不是 Ozon 原始导出的列格式，尚未连接其 Seller API。</p><button data-ops-action="template">下载标准模板</button><label class="file-import">导入记录<input id="ops-import" type="file" accept=".json,application/json"></label></details></section>`}
  function rulesForm(){const r=state.rules||{max_age_minutes:60,dispatch_warning_hours:24,overstock_days:90};return `<section class="card"><details><summary>本地提醒规则（可调整）</summary><p class="muted" data-ui-help>这些是本地默认参数，不是平台规定的履约期限。实际截止时间必须来自订单。</p><form id="ops-rules-form" novalidate><div class="analysis-fields">${[['max_age_minutes','数据有效期（分钟）'],['dispatch_warning_hours','临近发货预警提前（小时）'],['overstock_days','积压复核覆盖天数']].map(([key,label])=>`<label class="field"><span>${label}</span><input id="ops-rule-${key}" data-ops-rule="${key}" type="number" min="1" step="1" value="${esc(r[key])}"></label>`).join('')}</div><button type="submit">保存规则并重新检查</button></form></details></section>`}
  function campaignOutput(){
    if(state.comparisonBusy)return '<p class="empty" role="status">正在比较组合…</p>';
    if(state.comparisonError)return `<div class="alert error" role="alert">${esc(state.comparisonError)}</div>`;
    const result=state.comparison;if(!result)return '<p class="empty small" data-ui-help>填写成本与各方案参数后，比较优惠后的单件贡献和目标允许的每单广告费用。</p>';
    if(result.evidence&&JSON.stringify(result.evidence.input.base)!==JSON.stringify(getCostBase())){state.comparison=null;return '<div class="alert">成本参数已改变，请重新比较组合。</div>'}
    if(result.status==='HOLD')return `<div class="alert">成本资料未齐，请先在“成本测算”补全：${esc(result.missing.join('、'))}。</div>`;
    return `<div class="table-wrap"><table class="data-table"><thead><tr><th>组合</th><th>优惠后收入</th><th>每单广告</th><th>单件贡献</th><th>目标允许广告费 / 单</th></tr></thead><tbody>${result.plans.map(p=>`<tr><td>${esc(p.name)}</td><td>${money(p.net_revenue,result.currency)}</td><td>${money(p.ad_cost_per_unit,result.currency)}</td><td>${money(p.contribution,result.currency)}</td><td>${money(p.ad_allowance_at_target,result.currency)}${p.target_possible_before_ads?'':'（广告前已低于目标）'}</td></tr>`).join('')}</tbody></table></div>${result.plans.map(p=>`<p><strong>${esc(p.name)}：</strong>${esc(p.recommendation)}</p>`).join('')}<p class="muted">${result.assumptions.map(esc).join('<br>')}</p><button data-ops-action="campaign-export">导出组合与计算依据</button>`;
  }
  function campaign(){const base=getCostBase();return `<section class="card"><h2>投流、定价与促销组合</h2><p class="muted" data-ui-help>沿用“成本测算”中的币种、采购、物流和佣金等参数，单独填写每个组合的商家优惠、每单广告和达人佣金。结果为建议，不会修改价格或投放预算。</p><div class="alert">当前成本资料：${base.currency?esc(base.currency):'未选币种'}；采购成本 ${base.purchase_cost==null?'待填写':esc(base.purchase_cost)}。<button data-analysis-mode="cost">填写成本</button></div><div class="analysis-fields"><label class="field"><span>目标单件贡献（同币种）</span><input id="ops-target" type="number" min="0" step="any" data-ops-scenario="target_contribution" value="${esc(state.scenario.target_contribution)}"></label><label class="field"><span>库存情况（本次人工判断，尚未自动核实）</span><select data-ops-scenario="inventory_state">${[['unknown','尚未核实'],['sufficient','库存充足'],['tight','库存紧张'],['overstock','库存积压']].map(([k,v])=>`<option value="${k}" ${state.scenario.inventory_state===k?'selected':''}>${v}</option>`).join('')}</select></label></div><form id="ops-campaign-form" novalidate>${state.plans.map((p,i)=>`<fieldset class="ops-plan"><legend>组合 ${i+1}</legend><div class="analysis-fields">${[['name','方案名称'],['price','单件售价'],['merchant_discount','商家承担优惠 / 单'],['ad_cost_per_unit','每单分摊广告费'],['affiliate_rate','达人佣金率（%）']].map(([key,label])=>`<label class="field"><span>${label}</span><input id="ops-plan-${i}-${key}" data-ops-plan="${i}" data-part="${key}" type="${key==='name'?'text':'number'}" min="0" ${key==='affiliate_rate'?'max="100"':''} step="any" value="${esc(p[key])}"></label>`).join('')}</div></fieldset>`).join('')}<div class="form-actions"><button class="primary" type="submit">比较组合</button><button type="button" data-ops-action="campaign-example">填入演示组合</button></div></form><p class="muted" data-ui-help>达人佣金按优惠后收入计算；平台补贴不当成商家优惠重复扣。原成本表的广告比例不再计入，避免与本页每单广告重复。未填税费等需自行补入成本。</p></section><section class="card"><h2>组合测算结果</h2><div id="ops-campaign-output" aria-live="polite">${campaignOutput()}</div></section>`}
  function render(){return `<section class="ops-workspace"><div class="pills"><button class="pill ${state.tab==='alerts'?'active':''}" data-ops-tab="alerts">出单与补货提醒</button><button class="pill ${state.tab==='campaign'?'active':''}" data-ops-tab="campaign">投流与促销组合</button></div>${state.tab==='alerts'?alerts():campaign()}</section>`}
  function invalidate(){state.revision++;state.comparison=null;state.comparisonError='';state.comparisonBusy=false;const out=document.querySelector('#ops-campaign-output');if(out)out.innerHTML=campaignOutput()}
  async function saveRecord(){
    const f=state.form;for(const key of ['store_id','warehouse','sku','source_ref','observed_at'])if(!f[key].trim())throw Error('请填写店铺、仓库、SKU、核对时间和来源');
    const data=state.kind==='order'?{order_id:f.order_id,sku:f.sku,quantity:f.quantity===''?null:Number(f.quantity),status:f.status,ship_by:f.ship_by||null}:{sku:f.sku,...Object.fromEntries(stockFields.map(([key])=>[key,f[key]===''?null:Number(f[key])])),inbound_due_at:f.inbound_due_at||null};
    const values={platform:f.platform,store_id:f.store_id,market:f.market,fulfillment:f.fulfillment,warehouse:f.warehouse,observed_at:f.observed_at,source_ref:f.source_ref,kind:state.kind,data};
    const fingerprint=JSON.stringify(values);if(state.pending?.fingerprint!==fingerprint)state.pending={fingerprint,event_id:crypto.randomUUID()};
    const result=await api('commerce_ops_record',{record:{event_id:state.pending.event_id,...values},demo:state.demo});toast(result.status==='duplicate'?'相同记录已保存，没有重复提醒':result.status==='stored_history_only'?'较旧记录已留档，当前状态保持较新记录':'已保存来源并检查本地提醒');await load();
  }
  async function compare(){
    const revision=++state.revision;state.comparison=null;state.comparisonError='';
    try{
      const parse=(raw,label)=>{if(raw==='')throw Error('请填写'+label+'，没有该项请明确填 0');const value=Number(raw);if(!Number.isFinite(value)||value<0)throw Error(label+'需为有效非负数');return value};
      const input={base:getCostBase(),target_contribution:parse(state.scenario.target_contribution,'目标单件贡献'),inventory_state:state.scenario.inventory_state,plans:state.plans.map(p=>({name:p.name,price:parse(p.price,'售价'),merchant_discount:parse(p.merchant_discount,'商家优惠'),ad_cost_per_unit:parse(p.ad_cost_per_unit,'每单广告费'),affiliate_rate:parse(p.affiliate_rate,'达人佣金率')/100}))};
      state.comparisonBusy=true;document.querySelector('#ops-campaign-output').innerHTML=campaignOutput();const result=await api('commerce_campaign_compare',{input});if(revision===state.revision)state.comparison=result;
    }catch(error){if(revision===state.revision)state.comparisonError='组合测算未完成：'+error.message}
    finally{if(revision===state.revision){state.comparisonBusy=false;const out=document.querySelector('#ops-campaign-output');if(out)out.innerHTML=campaignOutput()}}
  }
  async function demo(){
    state.demo=true;const now=new Date(),root={platform:'ozon',store_id:'DEMO-OZON-RU',market:'RU',fulfillment:'FBS',warehouse:'DEMO-WH',observed_at:now.toISOString(),source_ref:'synthetic:local-example'};
    await api('commerce_ops_record',{demo:true,record:{...root,event_id:crypto.randomUUID(),kind:'order',data:{order_id:'DEMO-ORDER-1',sku:'DEMO-SKU-1',quantity:2,status:'awaiting_packaging',ship_by:new Date(now.getTime()+3600000).toISOString()}}});
    await api('commerce_ops_record',{demo:true,record:{...root,event_id:crypto.randomUUID(),kind:'stock',data:{sku:'DEMO-SKU-1',available:10,sold_units:60,window_days:30,lead_time_days:14,safety_days:7,pack_size:6,inbound_units:0,inbound_due_at:null}}});await load();
  }
  document.addEventListener('input',event=>{const e=event.target;if(e.dataset.opsField)state.form[e.dataset.opsField]=e.value;else if(e.dataset.opsRule){state.rules||={};state.rules[e.dataset.opsRule]=e.value}else if(e.dataset.opsScenario){state.scenario[e.dataset.opsScenario]=e.value;invalidate()}else if(e.dataset.opsPlan!==undefined){state.plans[Number(e.dataset.opsPlan)][e.dataset.part]=e.value;invalidate()}});
  document.addEventListener('change',async event=>{const e=event.target;if(e.id==='ops-scope'){state.demo=e.value==='demo';state.result=null;await load()}else if(e.dataset.opsField)state.form[e.dataset.opsField]=e.value;else if(e.dataset.opsScenario){state.scenario[e.dataset.opsScenario]=e.value;invalidate()}else if(e.id==='ops-import'){
    try{const file=e.files[0];if(!file)return;if(file.size>100000)throw Error('文件过大，请分批导入');const parsed=JSON.parse(await file.text()),records=Array.isArray(parsed)?parsed:[parsed];if(records.length>50)throw Error('每批最多 50 条');let n=0;for(const record of records){await api('commerce_ops_record',{record,demo:state.demo});n++}toast('已导入 '+n+' 条记录');await load()}catch(error){toast('导入停止：'+error.message+'。已成功保存的记录保留，可用相同事件标识继续导入。')}
  }});
  document.addEventListener('submit',async event=>{const id=event.target.id;if(!id.startsWith('ops-'))return;event.preventDefault();const b=event.target.querySelector('button[type="submit"]');if(b?.disabled)return;if(b)b.disabled=true;try{if(id==='ops-record-form')await saveRecord();else if(id==='ops-rules-form'){const rules=Object.fromEntries(Object.entries(state.rules).map(([k,v])=>[k,v===''?null:Number(v)]));await api('commerce_ops_rules',{rules,demo:state.demo});await load();toast('本地规则已更新')}else if(id==='ops-campaign-form')await compare()}catch(error){toast('操作未完成：'+error.message)}finally{if(b?.isConnected)b.disabled=false}});
  document.addEventListener('keydown',event=>{if(event.key==='Enter'&&event.target.matches('input')&&event.target.form?.id.startsWith('ops-')){event.preventDefault();event.target.form.dispatchEvent(new Event('submit',{bubbles:true,cancelable:true}))}});
  document.addEventListener('click',async event=>{
    const b=event.target.closest('button');if(!b)return;
    if(b.type==='submit'&&b.form?.id.startsWith('ops-')){event.preventDefault();event.stopImmediatePropagation();b.form.dispatchEvent(new Event('submit',{bubbles:true,cancelable:true}));return}
    if(b.dataset.opsTab){event.stopImmediatePropagation();state.tab=b.dataset.opsTab;repaint();return}if(b.dataset.opsKind){event.stopImmediatePropagation();state.kind=b.dataset.opsKind;repaint();return}
    const action=b.dataset.opsAction;if(!action)return;event.stopImmediatePropagation();b.disabled=true;
    try{
      if(action==='refresh')await load();else if(action==='demo')await demo();else if(action==='ack'){await api('commerce_ops_ack',{alert_id:b.dataset.id,demo:state.demo});await load()}
      else if(action==='now'){state.form.observed_at=new Date().toISOString();repaint()}
      else if(action==='export'){const result=await api('commerce_ops_export',{demo:state.demo});download(result.content,result.filename);toast('已导出来源记录与提醒历史')}
      else if(action==='campaign-export')download(JSON.stringify(state.comparison,null,2),'commerce-campaign-evidence.json');
      else if(action==='campaign-example'){state.scenario={target_contribution:'20',inventory_state:'unknown'};state.plans=[{name:'演示 A · 守价',price:'100',merchant_discount:'0',ad_cost_per_unit:'10',affiliate_rate:'0'},{name:'演示 B · 优惠',price:'100',merchant_discount:'10',ad_cost_per_unit:'10',affiliate_rate:'5'}];invalidate();repaint();toast('演示组合已填入，成本仍沿用成本测算中的参数')}
      else if(action==='template'){const record={event_id:'请填写唯一事件标识',platform:'ozon',store_id:'请填写店铺标识',market:'RU',fulfillment:'unknown',warehouse:'请填写仓库',observed_at:'请填写带时区的实际核对时间',source_ref:'请填写来源链接或文件行号',kind:'stock',data:{sku:'请填写SKU',available:null,sold_units:null,window_days:null,lead_time_days:null,safety_days:null,pack_size:null,inbound_units:null,inbound_due_at:null}};download(JSON.stringify(record,null,2),'commerce-observation-template.json')}
    }catch(error){toast('操作未完成：'+error.message)}finally{if(b.isConnected)b.disabled=false}
  });
  setInterval(()=>{if(isActive()&&state.tab==='alerts'&&!state.busy&&!document.activeElement?.closest('#ops-record-form,#ops-rules-form'))load()},30000);
  return {render,load,invalidate};
};

