window.CommerceLivePlans=({api,repaint,toast})=>{
  const ui=window.CommerceUI,esc=ui.escape;
  const state={readiness:null,data:null,key:'',input:{},saving:false,pending:null};
  const fields={sold_units:'窗口内销量（件）',window_days:'销量观察天数',lead_time_days:'补货到货天数',safety_days:'安全库存天数',pack_size:'每箱件数',inbound_units:'确认在途数量（没有请填 0）',inbound_due_at:'在途预计到达时间（带时区）',source_ref:'销量来源文件、行号或后台位置',demand_observed_at:'销量资料实际核对时间（带时区）'};
  const deliveryLabels={pending:'待发送',sending:'发送中',unknown:'结果不明，先核对群内',sent:'接口确认接收',failed:'失败或旧提醒已停止'};
  const labels={stock_source_changed_refresh_first:'库存快照已更新，请刷新后核对库存再保存。',stock_row_not_found:'该商品与履约范围已不存在，请重新选择。',future_demand_observation:'销量核对时间不能是未来时间。',invalid_observation_time:'请填写带时区的有效时间，例如使用下方的当前核对时间。',idempotency_conflict:'同一提交标识的内容发生变化，请刷新后重试。'};
  const button=(label,action,attrs={})=>ui.button({label,attrs:{'data-live-action':action,...attrs,disabled:state.saving}});
  async function load(){[state.readiness,state.data]=await Promise.all([api('commerce_live_readiness'),api('commerce_live_restock_list')]);}
  function readiness(){const r=state.readiness;if(!r)return '';return ui.card({title:`接入检查清单 · ${r.complete}/${r.total}`,content:ui.table(['检查项','状态','下一步'],r.checks.map(c=>`<tr><td>${esc(c.label)}</td><td>${ui.badge(c.status==='ready'?'已完成':'待处理',c.status==='ready'?'success':'warning')}</td><td>${c.status==='ready'?esc(c.detail):`${esc(c.detail)} ${button(c.action==='sync'?'同步一次':'打开接入向导',c.action==='sync'?'sync':'setup')}`}</td></tr>`))+`<h3>最近通知回执</h3><p class="muted">${esc(r.notice)}</p>`+ui.table(['状态','更新于','回执代码'],r.deliveries.map(d=>`<tr><td>${esc(deliveryLabels[d.status]||d.status)}</td><td>${esc(new Date(d.updated_at).toLocaleString())}</td><td><code>${esc(d.code||'尚无回执')}</code></td></tr>`),'尚无通知记录。配置并测试目标群后，实际发送回执会显示在这里。')});}
  function render(){
    if(!state.data)return '';
    const rows=state.data.candidates,row=rows.find(r=>r.key===state.key);
    const form=rows.length?`${ui.field('商品与履约范围（按产品 ID 区分）',ui.select({id:'live-plan-row',value:state.key,disabled:state.saving,options:[{value:'',label:'请选择一条真实库存记录'},...rows.map(r=>({value:r.key,label:`${r.offer_id||r.sku||r.product_id} · ${r.type} · 产品 ${r.product_id}`}))]}))}${row?`<p>平台原始 present：${row.present}；reserved：${row.reserved}；已核对可售：<strong>${row.available??'未知'}</strong>。${esc(row.scope)}。</p><p class="muted">来源时间：${esc(row.observed_at)} ${row.fresh?'':'（已过期）'}<br>库存快照 SHA-256：${esc(row.source_sha256)}</p><form id="live-restock-form" novalidate><div class="analysis-fields">${Object.entries(fields).map(([key,label])=>ui.field(label,ui.input({id:'live-plan-'+key,'data-live-plan-field':key,type:['inbound_due_at','source_ref','demand_observed_at'].includes(key)?'text':'number',value:state.input[key]??'',min:['window_days','pack_size'].includes(key)?1:0,step:1,maxlength:1000,disabled:state.saving}))).join('')}</div><div class="form-actions">${ui.button({label:state.saving?'正在保存…':'保存补货草稿',variant:'primary',attrs:{type:'submit',disabled:state.saving}})}${button('使用当前核对时间','plan-now')}</div></form>`:''}`:ui.empty('先完成一次库存只读同步，再选择实际商品与履约范围。');
    const plans=state.data.plans.map(p=>{const r=p.current_result;const missing=(r.missing||[]).map(k=>({available:'已核对可售库存',...fields})[k]||k);const reason=[...p.reason_zh,...missing.map(k=>'待补充：'+k),r.reason==='inbound_unknown'?'请明确在途数量与预计到达时间':'',r.reason==='no_demand_observed'?'观察期内销量为零，暂不推断采购量':''].filter(Boolean);return `<article class="ops-alert"><strong>${esc(p.stock.offer_id||p.stock.sku||p.stock.product_id)} · ${esc(p.stock.type)}</strong> ${ui.badge(r.status==='CALCULATED'?'待复核草稿':'资料不足或已失效',r.status==='CALCULATED'?'blue':'warning')}<p>${r.status==='CALCULATED'?`整箱建议 ${r.suggested_qty} 件；日均 ${r.velocity} 件；覆盖 ${r.days_of_cover} 天；可扣减在途 ${r.eligible_inbound} 件。`:'当前补货数量保持未知。'}${reason.map(esc).join('；')}</p><details><summary>查看来源和假设</summary><p class="muted">销量来源：${esc(p.input.source_ref||'待填写')}<br>销量核对时间：${esc(p.input.demand_observed_at||'待填写')}<br>库存来源：${esc(p.stock.observed_at)}<br>库存 SHA-256：${esc(p.snapshot_sha256)}<br>${esc(p.scope)}。按输入窗口外推；在途扣减需满足预计到达条件；草稿不执行采购。</p></details>${button('载入为新草稿','plan-load',{'data-plan-id':p.id})} ${button('导出草稿与证据','plan-export',{'data-plan-id':p.id})}</article>`}).join('');
    return readiness()+ui.card({title:'真实库存补货计划',attrs:{id:'live-planning'},content:`<p class="muted" data-ui-help>库存取所选产品 ID 和履约范围的快照；销量、交期和在途由你核对填写。发货单数不当作销量。缺项、未核对口径或来源过期时不生成确定补货量。销量资料需在 24 小时内核对。</p>${form}`})+ui.card({title:'已保存补货草稿',content:plans||ui.empty('尚未保存草稿。保存后可跨客户端查看，并导出中文字段说明和来源证据。')});
  }
  document.addEventListener('input',event=>{const key=event.target.dataset.livePlanField;if(!key)return;state.input[key]=event.target.value;state.pending=null});
  document.addEventListener('change',event=>{if(event.target.id==='live-plan-row'){state.key=event.target.value;state.input={};state.pending=null;repaint()}});
  async function save(){
    if(state.saving)return;const row=state.data?.candidates.find(r=>r.key===state.key);if(!row)return;
    const input={};for(const [key,value]of Object.entries(state.input)){if(value==='')continue;input[key]=['inbound_due_at','source_ref','demand_observed_at'].includes(key)?value:Number(value)}
    const frozen={row_key:row.key,source_sha256:row.source_sha256,input};const fingerprint=JSON.stringify(frozen);
    if(!state.pending||state.pending.fingerprint!==fingerprint)state.pending={fingerprint,key:crypto.randomUUID()};
    state.saving=true;repaint();
    try{await api('commerce_live_restock_save',{...frozen,idempotency_key:state.pending.key});await load();toast('补货草稿已保存，来源证据已绑定。')}
    catch(e){toast(labels[e.message]||(e.message.startsWith('invalid_')&&fields[e.message.slice(8)]?'请核对“'+fields[e.message.slice(8)]+'”：填写有效范围内的整数。':'未能保存：'+e.message))}
    finally{state.saving=false;repaint()}
  }
  document.addEventListener('submit',e=>{if(e.target.id!=='live-restock-form')return;e.preventDefault();save()});
  document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.form?.id==='live-restock-form'){e.preventDefault();save()}});
  document.addEventListener('click',e=>{const b=e.target.closest('button');if(b?.type==='submit'&&b.form?.id==='live-restock-form'){e.preventDefault();e.stopImmediatePropagation();save()}});
  async function action(name,b){if(name==='plan-load'){const p=state.data.plans.find(p=>p.id===b.dataset.planId);if(!p||!state.data.candidates.some(r=>r.key===p.stock.key)){toast('该产品与履约范围已不在当前库存中，请先同步核对。');return true}state.key=p.stock.key;state.input=Object.fromEntries(Object.entries(p.input).map(([k,v])=>[k,v==null?'':String(v)]));state.pending=null;repaint();toast('已载入原输入，请核对当前库存和资料时间后另存草稿。');return true}if(name==='plan-now'){state.input.demand_observed_at=new Date().toISOString();state.pending=null;repaint();return true}if(name==='plan-export'){const r=await api('commerce_live_restock_export',{plan_id:b.dataset.planId});const u=URL.createObjectURL(new Blob([r.content],{type:'application/json;charset=utf-8'}));const a=document.createElement('a');a.href=u;a.download=r.filename;a.click();setTimeout(()=>URL.revokeObjectURL(u),2000);return true}return false}
  function select(key){if(!state.data?.candidates.some(r=>r.key===key)){toast('该库存范围已变化，请刷新后重新选择。');return}if(state.key!==key){state.key=key;state.input={};state.pending=null}repaint();document.querySelector('#live-planning')?.scrollIntoView({block:'start'})}
  return {load,render,action,select,isEditing:()=>state.saving||!!document.activeElement?.closest('#live-restock-form,#live-plan-row')};
};

