/* Skill catalogue business UI; all base controls belong to CommerceUI. */
window.CommerceSkills=({api,esc,toast,repaint,isActive})=>{
 const ui=window.CommerceUI;
 const s={summary:null,list:null,selected:null,case:null,cases:[],caseLimit:10,query:'',repo:'all',platform:'all',area:'all',execution:'all',offset:0,busy:false,error:'',input:'{}',reference:null,request:0,synthetic:false,mode:'',draft:null,draftKey:null,draftEpoch:0,poll:null,methodOpen:false};
 const execution={unmapped:'无离线计算器',adapter_ready:'离线执行器可用',local_verified:'离线脚本已验证',live_verified:'真实账户已验证'};
 const stages={prepared:'待执行',needs_inputs:'待补数据',guidance_ready:'流程已准备',queued:'等待生成',awaiting_review:'草稿已生成 · 待审阅',unknown:'结果未知 · 未自动重试',cancelled:'请求前已取消',running:'运行中',completed:'离线完成 · 待业务核对',hold:'数据不足 / HOLD',failed:'执行失败',interrupted:'已中断 · 未自动重试'};
 const button=(label,action,attrs={},primary=false)=>ui.button({label,variant:primary?'primary':'secondary',attrs:{'data-skills-action':action,...attrs}});
 const select=(id,label,options,value)=>ui.field(label,ui.select({id:'skills-'+id,value,options:options.map(([value,label])=>({value,label}))}));
 function paint(){if(isActive())repaint()}
 function clearDraft(){s.draft=null;s.draftKey=null;s.draftEpoch++;clearTimeout(s.poll)}
 async function loadDraft(id){const epoch=++s.draftEpoch;clearTimeout(s.poll);const item=await api('commerce_skills_draft_get',{draft_id:id});if(epoch!==s.draftEpoch)return;s.draft=item;paint();pollDraft(epoch)}
 function pollDraft(epoch){clearTimeout(s.poll);if(!['queued','running'].includes(s.draft?.status))return;s.poll=setTimeout(async()=>{if(epoch!==s.draftEpoch||!isActive())return;try{const item=await api('commerce_skills_draft_get',{draft_id:s.draft.id});if(epoch!==s.draftEpoch)return;s.draft=item;paint();pollDraft(epoch)}catch(e){if(epoch===s.draftEpoch){s.error=error(e);paint()}}},1200)}
 function taskTemplate(mode){const value=structuredClone(s.selected.draft_input_template||{});const fields=Object.fromEntries([...new Set((mode?.capabilities||[]).flatMap(c=>c.required_fields||[]))].map(k=>[k,null]));return s.selected.draft_contract?{...value,parameters:fields}:fields}
 function sourcePosition(source){return source.path+' · '+(source.file_line_start?'第'+source.file_line_start+'行':source.heading+' · 节内第'+source.section_relative_line+'行')}
 function sourceMethodView(e){const m=e.source_method;if(!m)return '';const selected=m.mode_methods?.[s.mode],rows=['inputs','deliverables','procedures','boundaries'].flatMap(k=>m[k]).concat(selected?selected.inputs.concat(selected.deliverables):[]);return `${button(s.methodOpen?'收起原文方法索引':'展开原文方法索引','method_toggle',{'aria-expanded':s.methodOpen?'true':'false','aria-controls':'skills-source-method'})}<p class="muted">共同输入${m.inputs.length}项 · 交付${m.deliverables.length}项 · 流程${m.procedures.length}项 · 边界${m.boundaries.length}项${selected?' · 本次模式输入'+selected.inputs.length+'项':''}</p>${m.mode_selection_required&&!selected?ui.alert('已找到各模式的原文输入。请先选择本次模式；未选择时不会请求模型。','warning'):''}${s.methodOpen?`<section id="skills-source-method" aria-label="原文方法表"><p class="muted">原文候选项仍待领域审阅；来源包含已登记的正文、参考契约和本次模式，未穷尽其他参考。不同模式或工具路线的输入分别核对。</p>${m.extraction_gaps.length?ui.alert('仍有原文提取缺口，请核对完整流程。','warning'):''}${ui.table(['原文项','原文要求','原文位置'],rows.map(r=>`<tr><td>${esc(r.id)}</td><td>${esc(r.text)}</td><td>${esc(sourcePosition(r.source))}</td></tr>`))}</section>`:''}`}

 function requirementView(d){const rows=d.result?.requirement_checks;if(!rows)return '';const labels={covered_in_draft:'草稿自评已覆盖',partial:'部分覆盖',missing:'缺资料 / 未完成',not_applicable:'自评不适用'};const req=Object.fromEntries((d.contract.source_requirements||[]).map(r=>[r.id,r]));return `<section aria-label="原始要求对照"><h5>原始输入与交付要求对照</h5><p class="muted">以下为模型自评；结构检查只保证逐项列出和引用可解析，实际充分性仍需业务审阅。</p>${ui.table(['原始要求','模型自评','依据 / 草稿位置'],rows.map(r=>`<tr><td>${esc(r.requirement_id)} ${esc(req[r.requirement_id]?.text||'')}</td><td>${esc(labels[r.status])}<p>${esc(r.note)}</p></td><td>${esc(r.basis_refs.join(', '))}<br>${esc(r.section_ids.join(', '))}</td></tr>`))}</section>`}
 function contractView(e){const c=e.draft_contract;if(!c)return '';return ui.card({title:'本技能的草稿契约',content:`<p>${esc(c.label)} · 类型由规则归纳，须按原文核对适用性。</p><p class="muted">任务口径：${esc(c.required_scope.join('、')||'按本次任务明确范围')}；至少一条有来源的依据。</p><details><summary>原始输入与交付要求</summary><pre>${esc(c.source_input_excerpt+'\n\n'+c.source_delivery_excerpt)}</pre></details><p>交付章节：${esc(c.sections.join('、'))}</p>${sourceMethodView(e)}`})}
 function draftView(){const d=s.draft;if(!d)return '';const r=d.result||{},active=['queued','running'].includes(d.status);return `<section aria-label="技能草稿结果"><h4>${esc(stages[d.status]||d.status)}</h4><p class="muted">${d.synthetic?'合成输入 · ':''}来源${d.source_matches_current?'仍匹配':'已变化，请重新准备'}。F 为调用者依据，K 为方法参考；引用存在不代表事实已独立核实。</p>${r.error?ui.alert(esc(r.error),'warning'):''}${r.missing_fields?.length?ui.alert('待补：'+esc(r.missing_fields.join('、'))+'。本次未请求模型。','warning'):''}${(r.sections||[]).map(section=>`<h5>${esc(section.id)}</h5><ul>${section.items.map(v=>`<li>${esc(v.text)} <span class="muted">${esc(v.kind)} · ${esc(v.basis_refs.join(', '))}</span></li>`).join('')}</ul>`).join('')}${requirementView(d)}${r.questions?.length?`<h5>待补问题</h5><ul>${r.questions.map(v=>'<li>'+esc(v)+'</li>').join('')}</ul>`:''}${r.limitations?.length?`<p class="muted">${esc(r.limitations.join('；'))}</p>`:''}<details><summary>本次依据与参考范围</summary><pre>${esc(JSON.stringify({facts:d.task.facts,references:d.references.map(({content,...v})=>v),omitted:d.omitted_references},null,2))}</pre></details><div class="form-actions">${active?button('请求取消生成','draft_cancel'):''}${button('刷新草稿状态','draft_refresh')}${button('导出私有Markdown','draft_markdown',{disabled:active})}${button('导出私有JSON','draft_json',{disabled:active})}${r.sections&&!d.review&&d.source_matches_current?button('记录接受草稿','draft_accept')+button('记录退回草稿','draft_reject'):''}</div>${d.review?`<p role="status">调用者审阅：${d.review.decision==='accept'?'接受草稿':'退回草稿'}；这不代表独立核查或平台操作授权。</p>`:''}</section>`}
 function error(e){return ({sealeap_source_integrity_changed:'来源文件变化或缺失，请先重新核对固定版本。',sealeap_source_missing_or_unsafe:'固定版本源文件不可用，请检查本机来源快照。',sealeap_reference_not_registered:'该文件不在本技能的登记清单中。',idempotency_conflict:'同一任务键对应不同输入，请刷新后重新准备。',sealeap_input_too_large:'输入过大，请缩小到本次要核对的样本。',mode_required:'请先选择一个细分模式。',sealeap_adapter_changed_prepare_new_case:'执行器版本已变化，请用当前输入准备新任务。',invalid_json:'请输入有效的JSON对象。'}[e.message]||'操作未完成，请查看任务状态或稍后重试。')}
 async function search(){const request=++s.request;const result=await api('commerce_skills_search',{query:s.query,repo:s.repo,platform:s.platform,area:s.area,execution:s.execution,offset:s.offset,limit:20});if(request===s.request)s.list=result;paint()}
 async function enter(){try{const [summary,cases]=await Promise.all([api('commerce_skills_status'),api('commerce_skills_cases')]);s.summary=summary;s.cases=cases.cases;if(['running','queued'].includes(s.draft?.status))pollDraft(s.draftEpoch);await search()}catch(e){s.error=error(e);paint()}}
 async function open(id){const item=await api('commerce_skills_get',{skill_id:id});clearDraft();s.methodOpen=false;s.selected=item;s.reference=null;s.case=null;s.input='{}';s.synthetic=false;s.mode='';s.pending=null;paint()}
 function listView(){const result=s.list;return ui.card({title:'逐项覆盖清单',content:`<form id="skills-search-form"><div class="skills-filters">${ui.field('关键词',ui.input({id:'skills-query',value:s.query,placeholder:'例如：佣金、ACOS、库存、Listing'}))}${select('repo','来源',[['all','两个项目'],['ecommerce','多平台电商'],['amazon','亚马逊']],s.repo)}${select('platform','平台',[['all','全部'],...Object.keys(s.summary?.platforms||{}).map(x=>[x,x])],s.platform)}${select('area','方向',[['all','全部方向'],['research','选品研究'],['advertising','广告'],['inventory','库存履约'],['creative','商品与创意'],['operations','运营']],s.area)}${select('execution','执行状态',[['all','全部状态'],...Object.entries(execution)],s.execution)}</div>${button('检索技能','search',{},true)}</form><p class="muted">${result?.total||0} 项匹配</p>${ui.table(['技能','平台 / 方向','接入与验证','操作'],(result?.items||[]).map(e=>`<tr><td><strong title="${esc(e.id)}">${esc(e.title)}</strong></td><td>${esc(e.platform)}<br>${esc(e.area)}</td><td>${e.draft_family?'<p>'+esc(e.draft_family)+' · 草稿入口</p>':''}${ui.badge(execution[e.coverage.execution],e.coverage.execution==='local_verified'?'blue':'neutral')}${e.coverage.source==='missing'?'<p class="muted">本机快照缺失</p>':''}</td><td>${button('查看流程与缺口','open',{'data-skill':e.id})}</td></tr>`),'没有符合条件的技能。')}<div class="form-actions">${button('上一页','previous',{disabled:!s.offset})}<span>${(result?.offset||0)+1}–${Math.min((result?.offset||0)+(result?.items.length||0),result?.total||0)} / ${result?.total||0}</span>${button('下一页','next',{disabled:result?.next_offset===null})}${button('导出全量覆盖CSV','export')}</div>`})}
 function detailView(){const e=s.selected;if(!e)return '';return ui.card({title:e.title,content:`<p class="muted">固定来源版本 ${esc(e.commit.slice(0,12))} · ${esc(e.platform)} · ${e.integrity?'包文件哈希已核对':'来源缺失或变化'}</p><p>${esc(e.description)}</p>${ui.alert(e.adapter?'已接入本技能的一项离线脚本。脚本执行通过不等于当前规则、账户权限或完整技能验收。':'已接入按原文生成草稿或操作准备方案的入口。需要本次任务依据；输出待审阅，平台变更另行处理。')}<details><summary>技能正文与判断流程</summary><pre>${esc(e.skill_text||'源文件当前不可用。')}</pre></details><p class="muted">外部条件提示：${esc(e.external_prerequisites.join('、')||'以原文输入要求为准')}</p><div class="skills-references">${select('reference','配套参考文件',[['','请选择'],...e.files.filter(f=>f.path.endsWith('.md')).map(f=>[f.path,f.path])],s.reference?.path||'')}${button('读取所选参考','read')}</div>${s.reference?`<details open><summary>${esc(s.reference.path)}</summary><pre>${esc(s.reference.content)}</pre></details>`:''}${e.subcapabilities?.length?`<h3>入口内的细分模式</h3><p class="muted">工具要求是上游契约，未证明本机已接通或账户已授权。</p>${ui.table(['模式','范围 / 路由','所需工具与输入','参考'],e.subcapabilities.map(m=>`<tr><td>${esc(m.title)}<p class="muted">${esc(m.name)}</p></td><td>${esc(m.category)} · ${esc(m.route)}</td><td>${(m.capabilities||[]).map(c=>'<p>'+esc((c.provider||'')+' / '+(c.tool||'')+' · '+(c.required_fields||[]).join('、'))+'</p>').join('')||'以模式参考为准'}</td><td>${button('读取模式流程','mode',{'data-reference':m.reference,'data-mode':m.name})}</td></tr>`))}`:''}${e.subcapabilities?.length?`${select('mode','本次任务的细分模式',[['',e.source_method?.mode_selection_required?'请选择本次模式':'按整个技能准备'],...e.subcapabilities.map(m=>[m.name,m.title])],s.mode)}${button('填入模式输入模板','mode_template')}<p class="muted">自然语言输入见本次模式原文；模板只列已登记的工具字段，不代替完整输入要求。各工具路线分别核对。</p>`:''}${e.draft_contract?contractView(e):sourceMethodView(e)}<h3>结合本次任务准备</h3><p class="muted">填写本技能要求的JSON数据。分析任务的 facts 每条含 id（F1等）、text、source_ref、label（provided / synthetic / estimate / unknown）；真实缺项保持空值。模板不会虚构商品事实。</p>${ui.field('任务输入JSON',`<textarea class="ui-control" id="skills-input" rows="10" maxlength="96000" spellcheck="false">${esc(s.input)}</textarea>`)}<p role="status">${s.synthetic?'当前为合成样例':'当前为用户输入，待核对来源'}</p><div class="form-actions">${e.draft_contract?button('填入分析任务模板','task_template'):''}${e.example_input?button('填入合成样例','example'):''}${button('准备本机任务','prepare',{disabled:!e.integrity||s.busy},true)}${button('关闭技能详情','close')}</div>${caseView()}`})}
 function caseView(){const c=s.case;if(!c)return '';return `<section aria-label="技能任务结果"><h3>${esc(stages[c.status]||c.status)}</h3><p class="muted">${c.synthetic?'合成数据 · ':''}结果绑定来源包哈希 ${esc(c.source_sha256.slice(0,16))}。未提交平台变更。</p>${c.adapter&&c.status==='prepared'?button('执行离线计算器','execute',{disabled:s.busy},true):''}${c.status==='needs_inputs'?ui.alert('请先按技能要求补齐数据，再准备新任务。','warning'):''}${s.selected?.draft_contract?`<p class="muted">生成时会把本次输入和所选技能参考发送到现有模型，生成可审阅文本；图片和视频仅可提供文字解构依据，未在此生成媒体文件。</p>${button('按本技能生成草稿','generate',{disabled:s.busy||['queued','running'].includes(s.draft?.status)},true)}<div>${(c.drafts||[]).map(d=>button(stages[d.status]||d.status,'draft_open',{'data-draft':d.id})).join('')}</div>${draftView()}`:''}${c.output?.mode_plan?modePlanView(c.output.mode_plan):''}${c.output?.validation_scope?`<p class="muted">本次执行范围：${esc(c.output.validation_scope)}</p>`:''}<details open><summary>流程、结果与待补事项</summary><pre>${esc(JSON.stringify(c.output,null,2))}</pre></details></section>`}
 function modePlanView(p){return `<h4>细分模式：${esc(p.title)}</h4><p class="muted">只检查字段是否提供和本工作台是否登记该工具；账户资格与规则范围仍未核实，各工具是独立路线或阶段。</p>${ui.table(['工具','所需字段','待补字段','本工作台登记'],p.contracts.map(c=>`<tr><td>${esc(c.provider||'')} / ${esc(c.tool)}</td><td>${esc(c.required_fields.join('、')||'该工具未登记字段schema；模式输入见原文索引')}</td><td>${esc(c.missing_fields.join('、')||'已提供；仍需核对有效性')}</td><td>${c.registered_in_workbench?'已登记 · 资格待核实':'未登记 · 可核对其他客户端或授权导出'}</td></tr>`))}`}
 function view(){return `<section class="skills-workspace">${s.error?ui.alert(s.error,'danger'):''}<div class="skills-summary">${s.summary?`<p><strong>${s.summary.total}</strong> 项技能 · <strong>${s.summary.offline_adapters}</strong> 项可离线运行 · <strong>${s.summary.execution.local_verified||0}</strong> 项本机验证 · <strong>${s.summary.execution.live_verified||0}</strong> 项真实账户验证</p>`:ui.empty('正在读取能力清单。')}</div>${listView()}${detailView()}${ui.card({title:'最近技能任务',content:(s.cases||[]).slice(0,s.caseLimit).map(c=>`<p>${button((c.synthetic?'合成 · ':'')+c.skill_id+' · '+(stages[c.status]||c.status),'case',{'data-case':c.id,'data-skill':c.skill_id})}</p>`).join('')+((s.cases||[]).length>s.caseLimit?button('显示更多任务','more_cases'):'')||ui.empty('尚未创建技能任务。')})}</section>`}
 function download(content,name,mime){const url=URL.createObjectURL(new Blob([content],{type:mime})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000)}
 document.addEventListener('input',e=>{if(e.target.id==='skills-query')s.query=e.target.value;else if(e.target.id==='skills-input'){s.input=e.target.value;s.pending=null;s.case=null;clearDraft();document.querySelector('[aria-label="技能任务结果"]')?.remove()}});
 document.addEventListener('change',e=>{const key=e.target.id?.replace('skills-','');if(key==='mode'){s.mode=e.target.value;s.pending=null;s.case=null;clearDraft();document.querySelector('[aria-label="技能任务结果"]')?.remove();paint()}else if(['repo','platform','area','execution'].includes(key)){s[key]=e.target.value;s.offset=0}});
 document.addEventListener('submit',e=>{if(e.target.id==='skills-search-form'){e.preventDefault();e.stopImmediatePropagation();document.querySelector('[data-skills-action=search]')?.click()}});
 document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.id==='skills-query'){e.preventDefault();document.querySelector('[data-skills-action=search]')?.click()}});
 document.addEventListener('click',async e=>{const b=e.target.closest('[data-skills-action]');if(!b)return;e.preventDefault();e.stopImmediatePropagation();if(s.busy)return;const action=b.dataset.skillsAction;s.error='';s.busy=true;
  try{if(action==='method_toggle'){s.methodOpen=!s.methodOpen}else if(action==='more_cases'){s.caseLimit=30}else if(action==='search'){s.offset=0;await search()}else if(action==='next'){s.offset=s.list.next_offset;await search()}else if(action==='previous'){s.offset=Math.max(0,s.offset-20);await search()}else if(action==='open')await open(b.dataset.skill);else if(action==='close'){s.selected=null;s.case=null;clearDraft();document.querySelector('[aria-label="技能任务结果"]')?.remove()}else if(action==='read'){const path=document.getElementById('skills-reference').value;if(path)s.reference=await api('commerce_skills_read',{skill_id:s.selected.id,path})}else if(action==='mode'){s.reference=await api('commerce_skills_read',{skill_id:s.selected.id,path:b.dataset.reference});s.mode=b.dataset.mode;s.pending=null;s.case=null;clearDraft();document.querySelector('[aria-label="技能任务结果"]')?.remove()}else if(action==='mode_template'){const m=s.selected.subcapabilities.find(m=>m.name===s.mode);if(!m)throw Error('mode_required');s.input=JSON.stringify(taskTemplate(m),null,2);s.synthetic=false;s.pending=null;s.case=null;clearDraft();document.querySelector('[aria-label="技能任务结果"]')?.remove()}else if(action==='task_template'){s.input=JSON.stringify(taskTemplate(),null,2);s.synthetic=false;s.pending=null;s.case=null;clearDraft();document.querySelector('[aria-label="技能任务结果"]')?.remove()}else if(action==='example'){s.input=JSON.stringify(s.selected.example_input,null,2);s.synthetic=true;s.pending=null;s.case=null;clearDraft();document.querySelector('[aria-label="技能任务结果"]')?.remove()}else if(action==='prepare'){let input;try{input=JSON.parse(s.input);if(!input||typeof input!=='object'||Array.isArray(input))throw Error()}catch{throw Error('invalid_json')}const frozen=JSON.stringify([s.selected.id,s.mode,input,s.synthetic]);if(s.pending?.frozen!==frozen)s.pending={frozen,key:crypto.randomUUID()};const key=s.pending.key,result=await api('commerce_skills_prepare',{skill_id:s.selected.id,...(s.mode?{mode_id:s.mode}:{}),input,synthetic:s.synthetic,idempotency_key:key});if(s.pending?.key===key){s.case=result;clearDraft()}await enter()}else if(action==='execute'){const id=s.case.id,result=await api('commerce_skills_execute',{case_id:id});if(s.case?.id===id)s.case=result;await enter();toast('离线执行回执已保留，请核对计算范围。')}else if(action==='case'){await open(b.dataset.skill);s.case=await api('commerce_skills_case_get',{case_id:b.dataset.case});s.input=JSON.stringify(s.case.input,null,2);s.synthetic=s.case.synthetic;s.mode=s.case.mode_id||'';if(s.case.drafts?.length)await loadDraft(s.case.drafts[0].id)}else if(action==='generate'){const epoch=s.draftEpoch,caseId=s.case.id;s.draftKey=s.draftKey||crypto.randomUUID();const result=await api('commerce_skills_generate',{case_id:caseId,idempotency_key:s.draftKey});if(epoch===s.draftEpoch&&s.case?.id===caseId){s.draft=result;pollDraft(epoch)}}else if(action==='draft_open')await loadDraft(b.dataset.draft);else if(action==='draft_refresh')await loadDraft(s.draft.id);else if(action==='draft_cancel'){const id=s.draft.id;await api('commerce_skills_draft_cancel',{draft_id:id});await loadDraft(id)}else if(action==='draft_accept'||action==='draft_reject'){const epoch=s.draftEpoch,result=await api('commerce_skills_draft_review',{draft_id:s.draft.id,result_sha256:s.draft.result_sha256,decision:action==='draft_accept'?'accept':'reject'});if(epoch===s.draftEpoch)s.draft=result}else if(action==='draft_markdown'||action==='draft_json'){const format=action==='draft_json'?'json':'markdown',result=await api('commerce_skills_draft_export',{draft_id:s.draft.id,format});download(format==='json'?JSON.stringify(result,null,2):result.content,'skill-draft.'+(format==='json'?'json':'md'),format==='json'?'application/json':'text/markdown')}else if(action==='export'){const result=await api('commerce_skills_export',{format:'csv'});download('\ufeff'+result.content,'sealeap-coverage.csv','text/csv;charset=utf-8')}
  }catch(e){s.error=error(e)}finally{s.busy=false;paint()}
 });
 return {view,enter};
};
/* COMMERCE_SKILLS_END */
/* COMMERCE_CREATIVE_START */
/* Creative business module; primitives and themes belong to CommerceUI. */
window.CommerceCreative=({api,esc,toast,repaint,isActive})=>{
  const ui=window.CommerceUI;
  const state={projects:[],project:null,tab:'brief',busy:false,error:'',progress:'',job:null,preview:null,file:null,kind:'reference_video',asset:'',revision:0,form:{name:'',facts:'',transcript:'',source:'',language:'zh',country:''}};
  const labels={brief:'资料与素材',analysis:'原片拆解',scripts:'文案与分镜',outputs:'图片与视频'};
  const status={queued:'已排队',running:'处理中',completed:'已完成',partial:'部分完成 · 有待补充项',failed:'处理失败',interrupted:'已中断 · 未自动重发',unknown:'结果未知 · 不会自动重发',cancelled:'已取消'};
  const kinds={reference_video:'参考视频',product_image:'商品原图',audio:'补充音轨',captions:'字幕文件',generated_image:'已制作图片',generated_video:'已制作镜头',keyframe:'关键帧',image_layout_draft:'模板排版图',editable_layout:'可编辑排版',video_draft:'图文视频草稿',subtitle_file:'可编辑字幕'};
  const errorText=e=>({creative_analysis_required:'请选择已完成的原片分析任务。',creative_transcript_review_text_required:'请填写不超过6000字的校对口播。',creative_project_busy:'该项目仍在处理，请先查看当前任务。',creative_workers_busy_try_later:'本机处理任务已满，请稍后再试。',creative_revision_conflict_refresh_first:'资料已有新版本，请刷新后重新编辑。',creative_render_requires_product_asset_and_facts:'请先填写商品名称、卖点依据，并选择商品图或已制作镜头。',creative_reference_video_required:'请选择已导入的参考视频。',creative_product_image_required:'请选择已导入的商品图片。',creative_caption_too_long_shorten_product_facts:'文案较长，请缩短商品名称或卖点后再制作30秒草稿。',creative_media_limits_exceeded:'素材超出当前处理范围：视频最长120秒，图片最多1600万像素。',creative_unsupported_media:'当前支持MP4、WebM、PNG、JPEG、WAV及UTF-8字幕文件。',creative_upload_hash_or_size_mismatch:'文件校验未通过，请重新选择原文件导入。',creative_chunk_out_of_order:'上传进度未确认，请使用同一原文件重新导入以恢复。',creative_upload_closed:'上传已结束，请刷新素材列表。'}[e.message]||'操作未完成，请刷新项目后重试。');
  const button=(label,action,attrs={},primary=false)=>ui.button({label,variant:primary?'primary':'secondary',attrs:{'data-creative-action':action,...attrs}});
  const field=(key,label)=>ui.field(label,ui.input({id:'creative-'+key,'data-creative-field':key,value:state.form[key],maxlength:key==='name'?120:1000}));
  const area=(key,label,placeholder='')=>ui.field(label,`<textarea class="ui-control" id="creative-${key}" data-creative-field="${key}" rows="5" maxlength="6000" placeholder="${esc(placeholder)}">${esc(state.form[key])}</textarea>`);
  function formFrom(project){const b=project.brief;state.form={name:b.product?.name||'',facts:(b.product?.verified_facts||[]).map(f=>f.text+' | '+f.evidence_ref).join('\n'),transcript:b.reference?.transcript||'',source:b.reference?.source_url||'',language:b.target?.language||'zh',country:b.target?.country||''}}
  function brief(){return {synthetic:!!(state.pendingSynthetic||state.project?.brief.synthetic),product:{name:state.form.name.trim(),verified_facts:state.form.facts.split('\n').filter(x=>x.trim()).map((line,i)=>{const split=line.indexOf('|');if(split<0)throw Error('fact_format');const text=line.slice(0,split).trim(),source=line.slice(split+1).trim();if(!text||!source)throw Error('fact_format');return {id:'f'+(i+1),text,evidence_ref:source}})},reference:{source_url:state.form.source,transcript:state.form.transcript},target:{language:state.form.language,country:state.form.country}}}
  function paint(){if(isActive())repaint()}
  async function enter(){try{state.projects=(await api('commerce_creative_list')).projects;paint()}catch(e){state.error=errorText(e);paint()}}
  async function open(id){const revision=++state.revision;state.busy=true;paint();try{const project=await api('commerce_creative_get',{project_id:id});if(revision!==state.revision)return;state.project=project;state.audio='';state.file=null;state.progress='';state.asset=project.assets.find(a=>a.kind==='product_image')?.id||project.assets.find(a=>a.kind==='reference_video')?.id||'';state.job=null;state.watchedJob=null;state.transcriptJob=null;state.preview=null;state.error='';formFrom(project)}catch(e){state.error=errorText(e)}finally{if(revision===state.revision){state.busy=false;paint()}}}
  async function refresh(){if(!state.project)return;const id=state.project.id;const p=await api('commerce_creative_get',{project_id:id});if(state.project?.id===id)state.project=p;await enter()}
  function briefView(){return ui.card({title:'商品依据与参考资料',content:`<p class="muted" data-ui-help>参考片用于研究叙事与镜头；商品主张以你填写的资料依据为准。当前草稿仍需校对。</p><form id="creative-brief-form" novalidate><div class="analysis-fields">${field('name','商品名称')}${field('language','目标语言')}${field('country','目标国家 / 市场')}${field('source','参考视频来源链接（只记录来源）')}</div>${area('facts','商品卖点与依据','每行：一条商品事实 | 规格表或资料依据')}${area('transcript','原片口播 / 已校对字幕（可选）','粘贴已校对的口播或字幕')}<div class="form-actions">${button(state.project?'保存资料版本':'创建创意项目','save',{},true)}${button('填入合成示例','example')}</div></form>`})+ui.card({title:'私有素材',content:`<p class="muted">视频≤120秒，单文件≤32MB；请导入本地素材。</p><div class="analysis-fields">${ui.field('素材类别',ui.select({id:'creative-kind',value:state.kind,options:['reference_video','product_image','captions','generated_image','generated_video','audio'].map(k=>({value:k,label:kinds[k]}))}))}${ui.field('选择文件','<input class="ui-control" id="creative-file" type="file" accept="video/mp4,video/webm,image/png,image/jpeg,audio/wav,.srt,.vtt,.txt">')}</div><div class="form-actions">${button('导入所选素材','upload',{disabled:!state.project||!state.file||state.busy},true)}<span role="status">${esc(state.progress||state.file?.name||'尚未选择文件')}</span></div>${assetTable()}`})}
  function assetTable(){const assets=state.project?.assets||[];return ui.table(['素材','类别','来源状态','操作'],assets.map(a=>`<tr><td>${esc(a.display_name||a.id.slice(0,8))}</td><td>${esc(kinds[a.kind]||a.kind)}</td><td>${a.origin==='derived'?'本机衍生草稿':'用户导入 · 待核实'}</td><td>${button('预览 / 下载','asset',{'data-asset':a.id})}</td></tr>`),'尚未导入素材。')}
  function analysisView(){return ui.card({title:'原片拆解',content:`<p>检测画面切换候选、提取关键帧和画面文字，并读取口播。检测依据画面差异，闪光或快速移动也可能触发；不是语义分镜。</p><p class="muted">无切点时保留四个时间采样。机器转写需校对后回填，才会进入后续AI改写。</p>${assetSelect(['reference_video'])}${button('读取参考视频','analyze',{disabled:state.busy},true)}${analysisResult()}${jobView()}${assetTable()}`})}
  function analysisResult(){const j=state.job;if(j?.input.kind!=='analyze'||!j.result?.media)return '';const r=j.result,shots=r.shot_analysis,transcript=r.transcript||{};
    const reviewed=state.project?.brief.reference?.transcript_review?.source_job_id===j.id;if(state.transcriptJob!==j.id){state.transcriptJob=j.id;state.transcriptText=(reviewed?state.project.brief.reference.transcript:transcript.text)||''}
    return `<section class="creative-analysis" aria-label="原片分析结果"><h3>画面与口播</h3><p>${Number(r.media.duration_seconds).toFixed(2)}秒 · ${r.media.width}×${r.media.height} · ${r.media.has_audio?'含音轨':'无音轨'}</p><p class="muted">${shots?.method==='ffmpeg_visual_difference_candidates'?`检测到${shots.detected_cut_count}个画面切点候选${shots.omitted_cut_count?'；清单省略'+shots.omitted_cut_count+'个，部分区间包含多个切点':''}`:'本次未检测切点，显示时间采样'}。语义角色仍待人工解读。</p>${shots?.segments?.length?ui.table(['画面区间','时间'],shots.segments.map((s,i)=>`<tr><td>区间 ${i+1}</td><td>${s.start_seconds.toFixed(2)}–${s.end_seconds.toFixed(2)}秒</td></tr>`)):''}<div class="creative-frame-grid">${(r.keyframes||[]).map(f=>{const o=(r.ocr||[]).find(o=>o.asset_id===f.id);return `<article class="creative-frame"><strong>${Number(f.requested_timestamp_seconds).toFixed(2)}秒${f.fallback_to_first_frame?' · 回退首帧':''}</strong><p>${esc(o?.items?.map(x=>x.text).join('；')||'未识别到文字 / 识别不可用')}</p>${button('查看该关键帧','asset',{'data-asset':f.id})}</article>`}).join('')}</div>${ui.field('校对口播 / 字幕',`<textarea class="ui-control" id="creative-transcript-review" rows="6" maxlength="6000">${esc(state.transcriptText)}</textarea>`)}<p class="muted" id="creative-review-note">来源：${esc(reviewed?'调用者已校对 · 未独立核实':transcript.source==='local_whisper_tiny'?'本地语音转写 · 待校对':transcript.source==='not_available'?'尚无口播': '已提供文本 · 未独立核实')}。回填作为参考文案，商品事实保持独立；旧AI制作稿需重新审阅。</p>${button('已校对，回填参考文案','review_transcript',{'data-job':j.id,disabled:state.busy},true)}${(r.missing||[]).length?ui.alert('部分分析未完成，请结合关键帧与原片人工核对。','warning'):''}</section>`}
  function aiDraftView(){const j=state.job;if(j?.input.kind!=='refine'||!j.result?.scripts)return '';return `<section class="card"><h2>AI升级稿 · 待审阅</h2><p class="muted">已按目标语言请求改写，事实主张和翻译仍需核对。采用后才会进入视频制作。</p>${j.result.scripts.map(s=>`<article class="creative-script"><h3>${esc(s.hook)}</h3><p>${esc(s.body)}</p><p>${esc(s.cta)}</p>${s.warnings.includes('new_numbers_not_in_product_facts')?ui.alert('这版包含商品资料之外的数字，请重点核对。','danger'):''}${button('已核对，采用此稿','approve',{'data-angle':s.angle,'data-job':j.id})}</article>`).join('')}</section>`}
  function scriptsView(){const p=state.project?.plan;if(!p)return ui.empty('请先创建创意项目。');return ui.card({title:'三种切入点与分镜草稿',content:`${ui.badge(p.status==='draft_ready'?'本地模板草稿 · 待审阅':'待补充商品资料',p.status==='draft_ready'?'blue':'warning')}<p class="muted">本地正文只组合有来源卖点。点击AI升级时，会将所填商品文字和参考文案发送给既有模型，不上传原视频文件。</p>${button('AI升级三种文案','refine',{disabled:state.busy||p.status!=='draft_ready'},true)}${state.project?.brief.reviewed_script?ui.alert('已采用一份人工核对的制作稿，仍未独立核实商品主张。'):''}${aiDraftView()}${jobView()}${p.scripts.length?p.scripts.map((s,i)=>`<article class="creative-script"><h3>本地方案 ${i+1} · ${esc({detail:'商品细节',selection:'选购信息',demonstration:'演示说明'}[s.angle]||s.angle)}</h3><p><strong>开头：</strong>${esc(s.hook)}</p><p>${esc(s.body)}</p><p><strong>引导：</strong>${esc(s.cta)}</p><small class="muted">卖点依据：${s.fact_ids.map(esc).join('、')}</small></article>`).join(''):ui.empty('先填写商品名称与至少一条带依据的卖点。')}${ui.table(['片段','时间','制作事项'],p.video_plan.segments.map(s=>`<tr><td>${esc({hook:'开头',problem:'使用问题',demonstration:'产品演示',evidence_or_objection:'证据 / 异议',call_to_action:'行动引导'}[s.role])}</td><td>${s.start_ms/1000}–${s.end_ms/1000}秒</td><td>补充实际镜头、动作与资料，保持商品事实一致</td></tr>`))}<div class="form-actions">${button('导出项目JSON','export')}${button('导出制作清单Markdown','export_markdown')}</div>`})}
  function assetSelect(allowed){return ui.field('选择已导入素材',ui.select({id:'creative-asset',value:state.asset,options:[{value:'',label:'请选择'},...(state.project?.assets||[]).filter(a=>allowed.includes(a.kind)).map(a=>({value:a.id,label:(a.display_name||a.id.slice(0,8))+' · '+kinds[a.kind]}))]}))}
  function outputsView(){return ui.card({title:'图片与视频草稿',content:`<p>图片输出保留原图的三种模板排版和可编辑SVG。视频将商品素材与所选方案字幕组合成30秒图文草稿。</p><p class="muted">尚未自动抠图、生成真实使用场景或合成人物。可以导入已制作的图片、镜头和配音继续剪辑。</p>${assetSelect(['product_image','generated_image','generated_video'])}${ui.field('已导入的配音 / 音轨（可选）',ui.select({id:'creative-audio',value:state.audio||'',options:[{value:'',label:'不添加；镜头原有音轨会保留'},...(state.project?.assets||[]).filter(a=>a.kind==='audio').map(a=>({value:a.id,label:a.display_name||a.id.slice(0,8)}))]}))}${state.project?.brief.reviewed_script?ui.alert('视频使用已审阅AI稿；切换版本请到文案与分镜采用另一版。'):''}${ui.field('视频开头方案',ui.select({id:'creative-variant',value:state.variant||'0',disabled:!!state.project?.brief.reviewed_script,options:[{value:'0',label:'方案一 · 商品细节'},{value:'1',label:'方案二 · 选购信息'},{value:'2',label:'方案三 · 演示说明'}]}))}<div class="form-actions">${button('制作三种模板排版图','image_layout',{disabled:state.busy})}${button('渲染30秒视频草稿','render',{disabled:state.busy},true)}</div>${jobView()}${previewView()}${assetTable()}`})}
  function previewView(){if(!state.preview)return '';const p=state.preview;return `<div class="creative-preview">${p.mime.startsWith('image/')?`<img alt="私有创作素材预览" src="${p.url}">`:p.mime.startsWith('video/')?`<video controls playsinline src="${p.url}" aria-label="视频草稿预览"></video>`:''}<p>${esc(p.name)}</p>${button('下载该素材','download')}</div>`}
  function jobView(){const j=state.job,p=state.project;return `${j?`<section class="creative-job" role="status"><strong>${esc(status[j.status]||j.status)}</strong><p class="muted">资料版本 ${esc(j.input.revision)} · ${['queued','running'].includes(j.status)?'正在本机处理素材':'可查看已保留的处理结果'}${p&&j.input.revision!==p.revision?'；这是历史资料版本的结果':''}</p>${['queued','running'].includes(j.status)?'<p>'+esc(({visual_cut_detection:'正在检测画面切点',keyframes:'正在提取关键帧',transcript:'正在整理口播',local_asr:'正在本地转写',model_rewrite:'正在改写文案',rendering:'正在渲染视频'})[j.stage]||'正在处理素材')+'</p>':''}${['queued','running'].includes(j.status)?button('请求取消','cancel',{'data-job':j.id}):''}${j.result?`<details><summary>处理结果与限制</summary><pre>${esc(JSON.stringify(j.result,null,2))}</pre></details>`:''}</section>`:''}${(p?.jobs||[]).length?`<div class="creative-job-list">${p.jobs.slice(0,6).map(x=>button(({analyze:'原片分析',refine:'文案改写',image_layout:'图片排版',render:'视频制作'}[x.kind]||'任务')+' · '+(status[x.status]||x.status),'job',{'data-job':x.id,'data-job-kind':x.kind||''})).join('')}</div>`:''}`}
  function view(){return `<section class="creative-workspace">${state.error?ui.alert(state.error,'danger'):''}<div class="creative-projects">${button('新建项目','new',{},true)}${state.projects.map(p=>button((p.synthetic?'合成示例 · ':'')+p.name,'open',{'data-project':p.id,'aria-pressed':p.id===state.project?.id})).join('')}</div>${state.project?`<p class="muted">${esc(state.project.brief.product?.name||'未命名项目')} · 资料版本 ${esc(state.project.revision)} ${state.project.brief.synthetic?'· 合成测试资料':''}</p><div class="pills">${Object.entries(labels).map(([k,v])=>button(v,'tab',{'data-creative-tab':k,'aria-pressed':state.tab===k,class:'pill '+(state.tab===k?'active':'')})).join('')}</div>`:''}${state.tab==='brief'?briefView():state.tab==='analysis'?analysisView():state.tab==='scripts'?scriptsView():outputsView()}${state.tab==='outputs'?'':previewView()}</section>`}
  async function save(){if(!state.form.name.trim())throw Error('name_required');let b;try{b=brief()}catch{throw Error('fact_format')}
    if(state.project){state.project=await api('commerce_creative_save',{project_id:state.project.id,brief:b,revision:state.project.revision})}
    else{const frozen=JSON.stringify(b);if(state.pendingCreate?.frozen!==frozen)state.pendingCreate={frozen,key:crypto.randomUUID()};state.project=await api('commerce_creative_create',{brief:b,idempotency_key:state.pendingCreate.key})}
    state.error='';await enter();toast('已保存私有创作资料，草稿仍需审阅。')}
  async function upload(){const file=state.file,p=state.project;if(!file||!p)return;if(file.size>32*1024*1024)throw Error('file_too_large');if(!crypto.subtle)throw Error('file_hash_unavailable');const data=new Uint8Array(await file.arrayBuffer()),sha=[...new Uint8Array(await crypto.subtle.digest('SHA-256',data))].map(b=>b.toString(16).padStart(2,'0')).join('');const u=await api('commerce_creative_upload_begin',{project_id:p.id,filename:file.name,kind:state.kind,size:String(file.size),sha256:sha,source_ref:state.form.source||'user_provided_unverified'});
    if(!u.asset_id){for(let i=u.next_index;i<Math.ceil(data.length/u.chunk_bytes);i++){const bytes=data.subarray(i*u.chunk_bytes,(i+1)*u.chunk_bytes);let binary='';for(const b of bytes)binary+=String.fromCharCode(b);await api('commerce_creative_upload_chunk',{upload_id:u.upload_id,index:String(i),content_base64:btoa(binary)});state.progress='已导入 '+Math.min(100,Math.round((i+1)*u.chunk_bytes/data.length*100))+'%';paint()}}
    const completed=await api('commerce_creative_upload_finish',{upload_id:u.upload_id});if(state.project?.id===p.id){state.asset=completed.asset_id;state.progress='校验完成，素材已保存。';state.file=null;await refresh()}}
  async function job(action){const p=state.project;if(!p||(action!=='refine'&&!state.asset))throw Error('asset_required');const args={project_id:p.id};if(action!=='refine')args.asset_id=state.asset;if(action==='render'){args.variant=state.variant||'0';if(state.audio)args.audio_asset_id=state.audio}const frozen=JSON.stringify([action,p.revision,args]);state.keys||=new Map();if(!state.keys.has(frozen))state.keys.set(frozen,crypto.randomUUID());args.idempotency_key=state.keys.get(frozen);state.job=null;state.watchedJob=null;paint();const result=await api('commerce_creative_'+action,args);if(state.project?.id===p.id){state.job=result;watch(result.id,p.id);await refresh()}}
  function watch(id,project){state.watchedJob=id;poll(id,project)}
  async function poll(id,project){if(state.watchedJob!==id)return;try{const j=await api('commerce_creative_job_get',{job_id:id});if(state.project?.id!==project||state.watchedJob!==id)return;state.job=j;if(['queued','running'].includes(j.status)){paint();setTimeout(()=>poll(id,project),1500)}else await refresh()}catch(e){state.error='任务状态暂不可读；保留原任务，不会重复提交。';paint()}}
  async function readAsset(asset){const p=state.project,parts=[];let offset='0',result;do{result=await api('commerce_creative_asset_read',{project_id:p.id,asset_id:asset,offset});const b=atob(result.content_base64);parts.push(Uint8Array.from(b,c=>c.charCodeAt(0)));offset=result.next_offset}while(!result.done);return {blob:new Blob(parts,{type:result.mime}),mime:result.mime,extension:result.extension||''}}
  async function preview(asset){const p=state.project;const a=p.assets.find(x=>x.id===asset);const result=await readAsset(asset);if(state.project?.id!==p.id)return;const bytes=new Uint8Array(await result.blob.arrayBuffer());let binary='';for(const b of bytes)binary+=String.fromCharCode(b);state.preview={name:(a.display_name||'素材')+((a.display_name||'').toLowerCase().endsWith(result.extension)?'':result.extension),mime:result.mime,url:'data:'+result.mime+';base64,'+btoa(binary),blob:result.blob};paint()}
  function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000)}
  document.addEventListener('input',e=>{if(e.target.dataset.creativeField)state.form[e.target.dataset.creativeField]=e.target.value;else if(e.target.id==='creative-transcript-review')state.transcriptText=e.target.value});
  document.addEventListener('change',e=>{if(e.target.id==='creative-file'){state.file=e.target.files[0]||null;state.progress='';paint()}else if(e.target.id==='creative-kind')state.kind=e.target.value;else if(e.target.id==='creative-asset')state.asset=e.target.value;else if(e.target.id==='creative-variant')state.variant=e.target.value;else if(e.target.id==='creative-audio')state.audio=e.target.value});
  document.addEventListener('submit',e=>{if(e.target.id==='creative-brief-form'){e.preventDefault();e.stopImmediatePropagation();document.querySelector('[data-creative-action="save"]')?.click()}});
  document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.form?.id==='creative-brief-form'&&e.target.tagName==='INPUT'){e.preventDefault();document.querySelector('[data-creative-action="save"]')?.click()}});
  document.addEventListener('click',async e=>{const b=e.target.closest('[data-creative-action]');if(!b)return;e.preventDefault();e.stopImmediatePropagation();const action=b.dataset.creativeAction;if(state.busy&&!['cancel','tab'].includes(action))return;state.error='';
    try{if(action==='tab'){state.tab=b.dataset.creativeTab;const allowed=state.tab==='analysis'?['reference_video']:state.tab==='outputs'?['product_image','generated_image','generated_video']:null;if(allowed&&!state.project?.assets.some(a=>a.id===state.asset&&allowed.includes(a.kind)))state.asset='';paint();return}if(action==='new'){state.project=null;state.job=null;state.watchedJob=null;state.preview=null;state.pendingSynthetic=false;state.audio='';state.file=null;state.progress='';state.tab='brief';state.form={name:'',facts:'',transcript:'',source:'',language:'zh',country:''};paint();return}if(action==='example'){state.project=null;state.job=null;state.watchedJob=null;state.preview=null;state.audio='';state.file=null;state.progress='';state.form={name:'合成收纳盒',facts:'合成示例：容量为500毫升 | synthetic:spec-1',transcript:'这是合成参考文本，不代表真实商品或用户体验。',source:'synthetic:example',language:'zh',country:'示例市场'};state.pendingSynthetic=true;paint();return}
      state.busy=true;b.disabled=true;paint();if(action==='open')await open(b.dataset.project);else if(action==='save'){await save();state.pendingSynthetic=false}else if(action==='upload')await upload();else if(['analyze','render','image_layout','refine'].includes(action))await job(action);else if(action==='approve'){state.project=await api('commerce_creative_approve_script',{project_id:state.project.id,job_id:b.dataset.job,angle:b.dataset.angle,revision:state.project.revision});await refresh()}else if(action==='job'){state.job=await api('commerce_creative_job_get',{job_id:b.dataset.job});watch(state.job.id,state.project.id)}else if(action==='cancel'){await api('commerce_creative_job_cancel',{job_id:b.dataset.job});watch(b.dataset.job,state.project.id)}else if(action==='review_transcript'){state.project=await api('commerce_creative_review_transcript',{project_id:state.project.id,job_id:b.dataset.job,revision:state.project.revision,text:state.transcriptText||''});state.form.transcript=state.project.brief.reference.transcript;await refresh();toast('已回填参考文案；请重新审阅AI制作稿。')}else if(action==='asset')await preview(b.dataset.asset);else if(action==='download')download(state.preview.blob,state.preview.name);else if(action==='export_markdown'){const pack=await api('commerce_creative_export',{project_id:state.project.id,format:'markdown'});download(new Blob([pack.content],{type:'text/markdown;charset=utf-8'}),'creative-production-brief.md')}else if(action==='export')download(new Blob([JSON.stringify(await api('commerce_creative_export',{project_id:state.project.id}),null,2)],{type:'application/json'}),'creative-project-draft.json');
    }catch(error){state.error=({fact_format:'每条卖点请填写“商品事实 | 资料依据”。',name_required:'请填写商品名称。',asset_required:'请先选择已导入的素材。',file_too_large:'单文件最多32MB，请先截取需要研究的片段。',file_hash_unavailable:'当前窗口不支持文件校验，请在本机浏览器导入素材。'}[error.message]||errorText(error))}finally{state.busy=false;paint()}
  });
  return {view,enter};
};
