/* Shared read-only store UI. Credentials belong exclusively to local setup. */
window.CommercePlatforms=({api,esc,toast,repaint,modal,closeModal,isActive,onConnections})=>{
 const ui=window.CommerceUI,state={catalog:null,stores:[],storeId:'',resource:'',snapshot:null,error:'',job:null,generation:0,busy:false,days:7};
 const names={orders:'订单',products:'商品',stock:'库存'};
 const statusNames={queued:'排队中',running:'正在读取',succeeded:'读取完成',failed:'读取失败',unknown:'结果未知，不会自动重发',partial:'分页未全，原快照保留',superseded:'配置已变，结果未采用',cancel_requested:'正在停止',cancelled:'已取消'};
 const errors={platform_unexpected_schema:'平台返回结构与当前适配不符，原快照保留。',platform_provider_rejected:'平台拒绝本次读取，请核对应用权限与授权范围。',platform_http_failed:'平台响应未成功，原快照保留。',platform_read_budget_exceeded:'已到本轮读取上限，请缩小时间范围后明确提交新请求。',platform_incomplete_pagination:'分页未完整或读取中记录数发生变化，原快照保留。',platform_duplicate_records:'分页出现重复记录，结果未采用。',platform_pagination_repeated:'平台分页标识重复，结果未采用。',platform_configuration_changed:'连接配置已更新，请刷新后核对。',platform_credentials_missing:'请先在私有接入向导填写所需凭据。',platform_scope_review_required:'请先核对该授权与店铺、市场的对应关系。',platform_connection_disabled:'该连接尚未启用手动读取。',platform_permission_or_expired:'读取权限不足或授权已过期，请到私有向导核对。',platform_rate_limited:'平台限流，旧快照保留。不会自动重试。',platform_page_limit_old_snapshot_retained:'分页超过本轮上限，未采用部分结果，原快照保留。',platform_network_unknown_no_retry:'读取结果未知，旧快照保留；请先核对再明确发起新请求。',platform_scope_mismatch:'平台返回的店铺或市场与配置不符，结果未采用。',platform_current_snapshot_missing:'当前配置没有可导出的完整快照。',platform_connection_busy:'该店铺已有读取请求，请先查看其回执。'};
 const message=e=>errors[e.message]||e.message;
 const button=(label,action,attrs={})=>ui.button({label,attrs:{'data-platform-action':action,...attrs}});
 const store=()=>state.stores.find(s=>s.store_id===state.storeId);

 function jobView(){const j=state.job;if(!j)return '';return `<section class="card" aria-live="polite"><h2>本轮读取回执 ${ui.badge(statusNames[j.status]||j.status,j.status==='succeeded'?'blue':'gray')}</h2><p>${esc(j.error?message({message:j.error}):'完整读取后才保存新快照；任务完成不表示业务范围已验收。')}</p>${j.record_count!==null?`<p>本轮投影记录：${j.record_count} 条${j.complete?'':' · 未完整，未替换原快照'}</p>`:''}${['queued','running','cancel_requested'].includes(j.status)?button('停止本轮读取','cancel',{disabled:j.status==='cancel_requested'}):''}<p class="muted">${j.window?'本轮订单创建范围：'+esc(j.window.from)+' 至 '+esc(j.window.to):'本轮范围：所选店铺资源。'}<br>跨页读取可能遇到平台数据变化，仍需核对。</p></section>`}
 function snapshotView(){const s=state.snapshot;if(!s)return '';if(!s.available)return ui.empty(s.retained_previous?'配置已变化；旧证据仍保留，不混入当前店铺数据。':'当前没有完整快照。未知数据不会填为0。');const d=s.document;
  return `<section class="card"><div class="platform-heading"><h2>已保存快照 ${ui.badge(s.fresh?'有效期内，待业务核对':'已陈旧或连接停用','gray')}</h2>${button('导出私有证据','export')}</div><p class="muted">读取于 ${esc(new Date(d.observed_at*1000).toLocaleString())} · ${d.records.length} 条投影记录。${d.window?'创建时间范围：'+esc(d.window.from)+' 至 '+esc(d.window.to):''}</p>${ui.table(['原始标识 / SKU','名称或状态','平台原始数量','原币金额'],d.records.map(r=>`<tr><td>${esc(r.entity_id)}<br>${esc(r.sku||'')}</td><td>${esc(r.title||r.status||'未知')}</td><td>${r.quantity===null?'未知':r.quantity}<br><small class="muted">${esc(r.quantity_basis==='not_available'?'未接入数量口径':r.quantity_basis.includes('reference')?'区间参考值，不能用于采购':r.quantity_basis.includes('fba')?'FBA 可履约字段，非全部库存':'平台报告值，业务口径待核对')}</small></td><td>${r.amount===null?'未接入':esc(r.amount)+' '+esc(r.currency||'币种未知')}</td></tr>`))}<p class="muted">${esc(d.notice)} 导出含私有业务资料。金额不自动折汇或计入总览，读取成功不代表已完成对账。</p></section>`;
 }
 function view(){const c=store();return `<div class="platform-root"><section class="card"><div class="platform-heading"><h2>平台数据</h2>${button('管理连接','setup')}${button('刷新状态','refresh')}</div></section><section class="card"><h2>选择店铺与读取范围</h2>${ui.field('店铺',ui.select({id:'platform-store',value:state.storeId,options:[{value:'',label:'请选择，不自动选取店铺'},...state.stores.map(s=>({value:s.store_id,label:s.label+' · '+s.market+' · '+s.platform}))]}))}${c?`<p>${ui.badge(c.configured?'凭据字段已保存':'凭据待补','gray')} ${ui.badge(c.enabled?'允许手动读取':'手动读取未启用','gray')} ${ui.badge(c.scope_reviewed?'操作者已核对授权范围':'授权范围待核对','gray')}</p>${c.missing_fields.length?ui.alert('请在私有向导补充：'+c.missing_fields.map(esc).join('、')):''}<div class="platform-controls">${ui.field('资源',ui.select({id:'platform-resource',value:state.resource,options:c.resources.map(r=>({value:r,label:names[r]}))}))}${ui.field('订单创建窗口',ui.select({id:'platform-window',value:String(state.days),options:[{value:'1',label:'近1天'},{value:'7',label:'近7天'},{value:'30',label:'近30天'}]}))}${button('手动读取所选范围','read',{id:'platform-read',disabled:state.busy||!c.configured||!c.enabled||!c.scope_reviewed})}</div><p class="muted" data-ui-help>订单窗口截止于提交前约3分钟；单次最多3页，分页未全不会覆盖原快照。没有自动续期或通知。</p>`:ui.empty('尚无连接时先在私有向导添加；主界面不会索取或展示密钥。')}</section>${state.error?ui.alert(esc(state.error),'danger'):''}${jobView()}${snapshotView()}</div>`}
 async function select(){const generation=++state.generation,c=store();state.snapshot=null;state.job=c?.last_job||null;if(!c){if(isActive())repaint();return}if(!c.resources.includes(state.resource))state.resource=c.resources[0];const result=await api('commerce_platform_snapshot',{store_id:c.store_id,resource:state.resource});if(generation!==state.generation)return;state.snapshot=result;if(isActive())repaint()}
 async function enter(){try{const [catalog,result]=await Promise.all([api('commerce_platform_catalog'),api('commerce_platform_list')]);state.catalog=catalog;state.stores=result.stores;state.error='';if(state.storeId&&!store())state.storeId='';await select();if(isActive())repaint()}catch(e){state.error=message(e);if(isActive())repaint()}}
 document.addEventListener('change',event=>{if(event.target.id==='platform-window')state.days=Number(event.target.value);if(event.target.id==='platform-store'){state.storeId=event.target.value;select().catch(e=>toast(message(e)))}if(event.target.id==='platform-resource'){state.resource=event.target.value;select().catch(e=>toast(message(e)))}});
 document.addEventListener('click',async event=>{const b=event.target.closest('[data-platform-action]');if(!b)return;try{
  const action=b.dataset.platformAction;
  if(action==='setup'){onConnections();return}
  else if(action==='refresh')await enter();
  else if(action==='read'){const c=store();b.focus();modal('确认本轮只读范围',`<p>${esc(c.label)} · ${esc(c.platform)} · ${esc(c.market)}</p><p>资源：${esc(names[state.resource])}。${state.resource==='orders'?'订单创建窗口：'+esc(document.querySelector('#platform-window').value)+'天，截止约3分钟前。':'读取所选店铺资源。'}</p><p data-ui-help>仅读取平台资料并保存本地证据，不改价、发货、退款或发送消息。</p>`,button('确认读取','confirm',{'data-store':c.store_id,'data-revision':c.revision,'data-resource':state.resource,'data-days':document.querySelector('#platform-window').value,'data-key':crypto.randomUUID()}))}
  else if(action==='confirm'){b.disabled=true;state.busy=true;const j=await api('commerce_platform_sync',{store_id:b.dataset.store,resource:b.dataset.resource,expected_revision:b.dataset.revision,window_days:Number(b.dataset.days),max_pages:3,idempotency_key:b.dataset.key});closeModal();if(state.storeId===j.store_id){state.job=j;await enter()}}
  else if(action==='cancel'){await api('commerce_platform_cancel',{job_id:state.job.id});await enter()}
  else if(action==='export'){const file=await api('commerce_platform_export',{store_id:state.storeId,resource:state.resource}),url=URL.createObjectURL(new Blob([file.content],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=file.filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000)}
 }catch(e){toast('操作未完成：'+message(e))}finally{state.busy=false;if(b.isConnected)b.disabled=false;if(isActive()&&!document.querySelector('.dialog'))repaint()}});
 setInterval(async()=>{if(!isActive()||!state.job||!['queued','running','cancel_requested'].includes(state.job.status)||document.querySelector('.dialog'))return;const id=state.job.id,generation=state.generation;try{const j=await api('commerce_platform_job',{job_id:id});if(generation!==state.generation||state.job?.id!==id)return;state.job=j;if(!['queued','running','cancel_requested'].includes(j.status))await enter();else repaint()}catch{}},1500);
 return {view,enter};
};
