  const analysis={mode:window.__COMMERCE_LEGACY__?.mode==='stock'?'stock':'cost',cost:{values:{},revision:0,origin:'manual',busy:false,result:null,error:''},stock:{values:{},revision:0,origin:'manual',busy:false,result:null,error:''}};
