  function analysisOutput(kind){
    const item=analysis[kind],r=item.result;
    if(item.busy)return '<p class="empty small" role="status">正在测算…</p>';
    if(item.error)return `<div class="alert error" role="alert">${esc(item.error)}</div>`;
    if(!r)return kind==='stock'?'<div class="empty small">尚未生成补货建议。</div>':'<div class="empty small">尚未生成测算结果。<br>未知费用留空；确认没有该项费用时填 0。</div>';
    if(r.status==='HOLD'){
      const names={currency:'币种',...Object.fromEntries(analysisFields[kind].map(([key,label])=>[key,label]))};
      return `<div class="alert" role="status"><strong>待补数据</strong><p>${r.reason==='no_demand_observed'?'观察期内没有销量，暂不能据此推算补货量。请补充有代表性的销量窗口，再重新测算。':'请补全：'+r.missing.map(key=>names[key]||key).join('、')+'。'}</p></div>`;
    }
    const source=organization.receiptHtml(r.artifact_handoff)+`<button type="button" data-action="analysis-export" data-kind="${kind}">导出测算依据</button><p class="muted">输入来源：${item.origin==='example'?'演示样例（非真实业务数据）':item.origin==='edited-example'?'演示样例经手动修改，请核对全部参数':'本次手动填写'} · 测算草稿</p>`;
    if(kind==='cost'){
      const componentNames={purchase_cost:'采购成本',domestic_shipping:'国内运费',packaging:'包装成本',fulfillment_cost:'履约费用',electronic_fee:'其他固定费用',commission:'平台佣金',payment:'支付费用',return:'退货预留',ad:'广告费用'};
      return `${source}<div class="result-metrics"><div><span>单件贡献</span><strong data-metric="contribution" class="${r.contribution<0?'negative':''}">${esc(money(r.contribution,r.currency))}</strong></div><div><span>贡献率</span><strong data-metric="contribution-rate">${decimal(r.contribution_rate*100)}%</strong></div><div><span>单件总成本</span><strong data-metric="total-cost">${esc(money(r.total_cost,r.currency))}</strong></div></div><dl class="cost-breakdown">${Object.entries(r.cost_breakdown).map(([key,value])=>`<div><dt>${componentNames[key]||esc(key)}</dt><dd>${esc(money(value,r.currency))}</dd></div>`).join('')}</dl><p class="muted">所有金额均为 ${esc(r.currency)}，不自动换汇；各比例以售价为基数，费用逐项保留两位小数。单件贡献用于对比方案，未填写的税费等需自行计入，不能代替净利润或结算账单。</p>`;
    }
    const priority={P0:'P0 · 预计无法覆盖到货周期',P1:'P1 · 低于安全库存覆盖',P2:'P2 · 当前覆盖充足'};
    return `${source}${badge(priority[r.urgency]||r.urgency,r.urgency==='P0'?'':'blue')}<div class="result-metrics"><div><span>建议补货量</span><strong data-metric="suggested-qty">${decimal(r.suggested_qty)} 件</strong></div><div><span>库存覆盖</span><strong data-metric="days-cover">${decimal(r.days_of_cover)} 天</strong></div><div><span>日均销量</span><strong data-metric="velocity">${decimal(r.velocity)} 件</strong></div></div><p>目标库存：<strong>${decimal(r.target_units)} 件</strong>；补货数量已向上取整到整箱。</p><p class="muted" data-ui-help>按输入的销量窗口推算，不保证未来需求。当前可售库存不含在途到货，请先核实在途、缺货和促销影响，再据此安排补货。</p>`;
  }
  function operations(){
    const kind=analysis.mode,item=analysis[kind];
    return `${kind==='cost'?workspaceUI.disclosure(organization.bindingView('economics'),{id:'cost-binding',title:'选填：关联商品工作项与交付'}):''}<section class="operations-shell">${workspaceUI.draftControls(kind,formScope(kind))}<div class="pills" aria-label="测算类型">${(reactHost?[]:[['cost','成本测算'],['stock','补货计划']]).map(([key,label])=>`<button class="pill ${kind===key?'active':''}" data-analysis-mode="${key}" aria-pressed="${kind===key}">${label}</button>`).join('')}</div><p class="muted" data-ui-help>按本次填写的参数计算，不受概览的模拟数据或店铺筛选影响。结果供审阅，不会下采购单或修改库存。</p><div class="analysis-layout"><section class="card"><h2>${icon(kind==='cost'?'doc':'box')}${kind==='cost'?'单件成本与贡献':'补货参数'}</h2><p class="muted">${kind==='cost'?'金额使用同一币种；比例填百分数，例如 10 表示 10%。':'使用同一商品、同一库存范围的实际销量与库存。'}</p><form id="analysis-form" data-kind="${kind}" novalidate><div class="analysis-fields">${kind==='cost'?`<label class="field"><span>测算币种</span><select id="analysis-currency" name="currency" data-analysis-field="cost"><option value="">请选择币种</option>${currencyOptions.map(([code,label])=>`<option value="${code}" ${item.values.currency===code?'selected':''}>${code} · ${label}</option>`).join('')}</select></label>`:''}${analysisFields[kind].map(([key,label,min,max])=>`<label class="field" for="analysis-${key}"><span>${label}${key.endsWith('_rate')?'（%）':kind==='cost'?'（单件）':''}</span><input id="analysis-${key}" name="${key}" data-analysis-field="${kind}" type="number" inputmode="${kind==='stock'?'numeric':'decimal'}" min="${min}" max="${max}" step="${kind==='stock'?'1':'any'}" value="${esc(item.values[key]??'')}" placeholder="待填写"></label>`).join('')}</div><div class="form-actions"><button class="primary" type="submit" ${item.busy?'disabled':''}>${item.busy?'正在测算…':kind==='cost'?'计算单件贡献':'生成补货计划'}</button><button type="button" data-analysis-example="${kind}">填入演示样例</button><button type="button" data-analysis-clear="${kind}">清空</button></div><p class="muted">${item.origin==='example'?'当前为演示样例，请替换为实际参数。':item.origin==='edited-example'?'当前参数由演示样例修改，请核对每一项。':'参数仅保留在当前面板，刷新或关闭后需重新填写。'}</p></form></section><section class="card analysis-result" aria-labelledby="analysis-result-title"><h2 id="analysis-result-title">${kind==='cost'?'测算结果':'补货建议'}</h2><div id="analysis-output" aria-live="polite" aria-atomic="true">${analysisOutput(kind)}</div></section></div></section>`;
  }
  function renderAnalysis(){
    const kind=analysis.mode,output=document.querySelector('#analysis-output'),submit=document.querySelector('#analysis-form button[type="submit"]');
    if(output)output.innerHTML=analysisOutput(kind);
    if(submit){submit.disabled=analysis[kind].busy;submit.textContent=analysis[kind].busy?'正在测算…':kind==='cost'?'计算单件贡献':'生成补货计划'}
  }
  function invalidateAnalysis(kind){const item=analysis[kind];item.revision++;item.result=null;item.error='';item.busy=false;if(item.origin==='example')item.origin='edited-example';if(analysis.mode===kind)renderAnalysis()}
  async function calculate(kind,form){
    const item=analysis[kind],revision=++item.revision,input={};item.result=null;item.error='';
    for(const control of form.elements){
      if(!control.name)continue;
      const raw=control.value.trim();
      if(control.validity?.badInput||raw&&!control.checkValidity()){item.error='请检查标出的参数：金额和比例需在允许范围内，天数与件数需为整数。';control.setAttribute('aria-invalid','true');control.focus();renderAnalysis();return}
      control.removeAttribute('aria-invalid');
      if(!raw)continue;
      input[control.name]=control.name==='currency'?raw:Number(raw)/(control.name.endsWith('_rate')?100:1);
    }
    item.busy=true;renderAnalysis();
    try{const result=await (kind==='cost'?organization.produce('commerce_unit_economics',{input},{origin:item.origin}):api('commerce_restock_plan',{input}));if(revision===item.revision)item.result=result}
    catch(error){if(revision===item.revision)item.error='测算失败，请检查参数或稍后重试。'+error.message}
    finally{if(revision===item.revision){item.busy=false;if(state.tab==='operations'&&analysis.mode===kind)renderAnalysis()}}
  }
  function knowledgeOutput(){
    if(!state.connections?.knowledge?.configured)return '<div class="empty small">业务知识目录尚未配置。配置后可搜索该目录内的中文或英文 Markdown 笔记。</div>';
    if(knowledge.busy)return '<p class="empty small" role="status">正在检索业务知识…</p>';
    if(knowledge.error)return `<div class="alert error" role="alert">${esc(knowledge.error)}</div>`;
    if(!knowledge.result)return '<p class="muted" data-ui-help>支持中文运营词匹配英文笔记，如“补货”“库存”“退款”。检索结果保留原文语言。</p>';
    const hits=knowledge.result.hits;
    return hits.length?`<p class="muted">找到 ${hits.length} 条相关笔记，可打开原文核对。</p><ul class="knowledge-hits">${hits.map(hit=>`<li><button data-note="${esc(hit.path)}">${icon('book')}<span>${esc(hit.path)}</span><span class="open-note">打开原文 ›</span></button><p>${esc(hit.excerpt)}</p></li>`).join('')}</ul>`:'<div class="empty small">没有找到相关笔记。试试同义词，或确认资料已放入业务知识目录。</div>';
  }
  function knowledgeView(){return `<section class="card" id="knowledge-center"><h2>${icon('book')}中英业务知识检索</h2><p class="muted">只检索已配置的业务目录，可用中文或英文查询。</p><form id="knowledge-search-form" class="knowledge-search"><label for="knowledge-query">搜索业务知识</label><div><input id="knowledge-query" name="query" type="search" maxlength="80" value="${esc(knowledge.query)}" placeholder="例如：补货、库存、restock" autocomplete="off"><button type="submit" class="primary" ${knowledge.busy?'disabled':''}>${knowledge.busy?'检索中…':'搜索'}</button></div></form><div id="knowledge-output" aria-live="polite" aria-atomic="true">${knowledgeOutput()}</div><details class="knowledge-directory"><summary>业务知识目录（${state.notes.length} 篇）</summary>${state.notes.length?`<ul class="knowledge-list">${state.notes.map(p=>`<li>${icon('book')}<button data-note="${esc(p)}">${esc(p)}</button></li>`).join('')}</ul>`:'<div class="empty small">暂无业务笔记</div>'}${btn('刷新知识目录','knowledge')}</details></section>`}
  function renderKnowledge(){const output=document.querySelector('#knowledge-output'),button=document.querySelector('#knowledge-search-form button');if(output)output.innerHTML=knowledgeOutput();if(button){button.disabled=knowledge.busy;button.textContent=knowledge.busy?'检索中…':'搜索'}}
  async function searchKnowledge(){
    const query=knowledge.query.trim(),revision=++knowledge.revision;knowledge.result=null;knowledge.error='';
    if(!query){knowledge.busy=false;knowledge.error='请填写要搜索的中文或英文关键词。';renderKnowledge();document.querySelector('#knowledge-query')?.focus();return}
    if(!state.connections?.knowledge?.configured){knowledge.busy=false;renderKnowledge();return}
    knowledge.busy=true;renderKnowledge();
    try{const result=await api('commerce_knowledge_search',{query});if(revision===knowledge.revision)knowledge.result=result}
    catch(error){if(revision===knowledge.revision)knowledge.error='检索失败，请稍后重试。'+error.message}
    finally{if(revision===knowledge.revision){knowledge.busy=false;renderKnowledge()}}
  }
  const collection={platform:'research',drafts:{},spec:null,record:null,revision:0,check:null,error:'',loading:false,translation:null};
  function download(content,name,type){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000)}
  async function openCollection(platform){
    if(collection.record)collection.drafts[collection.record.platform]=collection.record;
    const revision=++collection.revision;collection.platform=platform;collection.loading=true;collection.check=null;collection.error='';paint();
    try{const spec=await api('commerce_collection_template',{platform});if(revision===collection.revision){collection.spec=spec;collection.record=collection.drafts[platform]||spec.record}}
    catch(error){if(revision===collection.revision)collection.error='采集模板加载失败：'+error.message}
    finally{if(revision===collection.revision){collection.loading=false;paint()}}
  }
  function collectionFeedback(){
    if(collection.error)return `<div class="alert error" role="alert">${esc(collection.error)}</div>`;
    if(!collection.check)return '<p class="muted" data-ui-help>填写后检查缺项。原文、中文、来源位置和校对状态都会保留在导出文件中。</p>';
    return collection.check.issues.length?`<div class="alert" role="status"><strong>当前为草稿，${collection.check.issues.length} 项待处理</strong><ul>${collection.check.issues.map(x=>`<li>${esc(x.message)}</li>`).join('')}</ul></div>`:'<div class="alert" role="status">资料完整性检查通过。可导出经审阅资料；来源仍需独立核实，不能据此认定商品可直接上架。</div>';
  }
  function renderCollectionFeedback(){const target=document.querySelector('#collection-feedback');if(target)target.innerHTML=organization.receiptHtml(collection.check?.artifact_handoff)+collectionFeedback()}
  function formScope(kind){return {module:kind==='research'?'research':'operations',form:kind==='research'?collection.platform:kind,case_id:document.querySelector('#org-binding-'+(kind==='research'?'research':'economics'))?.value||''}}
  let pendingFormRestore=null,formRestoreGeneration=0;
  const formRevision=kind=>kind==='research'?collection.revision:analysis[kind].revision;
  async function saveForm(kind){const scope=formScope(kind);const payload=JSON.parse(JSON.stringify(kind==='research'?{record:collection.record}:{values:analysis[kind].values,origin:analysis[kind].origin}));try{await workspaceUI.saveDraft(scope,payload)}catch(error){if(error.message==='form_draft_conflict')throw Error('草稿已在其它窗口更新。请先恢复最新草稿，再修改并保存；当前输入已保留。');throw error}toast('输入草稿已保存在本机，未提交分析或交付。')}
  async function restoreForm(kind){const scope=formScope(kind),id=++formRestoreGeneration,revision=formRevision(kind),view=state.tab,saved=await workspaceUI.readDraft(scope);if(id!==formRestoreGeneration||view!==state.tab||revision!==formRevision(kind)||JSON.stringify(formScope(kind))!==JSON.stringify(scope))throw Error('表单已变化，请重新读取草稿');if(!saved.payload){toast('当前表单范围没有已保存草稿。');return}pendingFormRestore={id,revision,view,kind,scope,saved};dialog('恢复已保存的输入',`<p>将替换当前${kind==='research'?'调研资料':'测算参数'}中的输入。</p><p>保存时间：${esc(new Date(saved.saved_at*1000).toLocaleString())}</p>`,ui.button({label:'恢复这些输入',variant:'primary',action:'form-restore-apply'}))}
  async function applyFormRestore(){const pending=pendingFormRestore;const current=()=>pending&&pendingFormRestore===pending&&pending.id===formRestoreGeneration&&state.tab===pending.view&&formRevision(pending.kind)===pending.revision&&JSON.stringify(formScope(pending.kind))===JSON.stringify(pending.scope);if(!current())throw Error('表单已变化或恢复已取消，请重新读取草稿');const {kind,saved}=pending,p=saved.payload;if(kind==='research'){if(p.record?.platform!==collection.platform)throw Error('草稿模板范围不一致');await api('commerce_collection_check',{record:p.record});if(!current())throw Error('表单已变化或恢复已取消，请重新读取草稿');collection.record=JSON.parse(JSON.stringify(p.record));collection.check=null;collection.revision++;collection.error=''}else{if(!p.values||!['manual','example','edited-example'].includes(p.origin))throw Error('草稿输入格式无效');const allowed=new Set(['currency',...analysisFields[kind].map(([key])=>key)]);if(Object.entries(p.values).some(([k,v])=>!allowed.has(k)||!['string','number'].includes(typeof v)))throw Error('草稿字段已变化，请重新核对');analysis[kind].values={...p.values};analysis[kind].origin=p.origin;analysis[kind].result=null;analysis[kind].revision++;analysis[kind].error=''}pendingFormRestore=null;close();paint();toast('已恢复输入')}
  function researchView(){
    const r=collection.record,spec=collection.spec;
    const meta=(key,label,large=false)=>`<label class="field"><span>${label}</span>${large?`<textarea rows="5" data-collection-meta="${key}">${esc(r[key])}</textarea>`:`<input type="text" data-collection-meta="${key}" value="${esc(r[key])}">`}</label>`;
    return `${workspaceUI.disclosure(organization.bindingView('research'),{id:'research-binding',title:'选填：关联商品工作项与交付'})}<section class="card"><h2>${icon('book')}调研、翻译与来源证据</h2><p class="muted" data-ui-help>资料按“原文＋中文＋来源”留存。原文保持不变；模型译文默认待校对，推算和冲突单独标记。</p>${workspaceUI.draftControls('research',formScope('research'))}<div class="collection-toolbar"><label class="field"><span>采集模板</span><select id="collection-platform">${[['research','通用调研'],...Object.entries(names)].map(([key,label])=>`<option value="${key}" ${collection.platform===key?'selected':''}>${label}</option>`).join('')}</select></label><button data-action="collection-template" ${!spec||collection.loading?'disabled':''}>下载空白模板</button><label class="file-import">导入 JSON 草稿<input id="collection-import" type="file" accept=".json,application/json"></label></div>${collection.loading?'<p class="loading">正在加载采集模板…</p>':!r||!spec?`<div class="alert error" role="alert">${esc(collection.error||'模板尚未加载')}</div>${btn('重新加载模板','collection-reload')}`:`<p class="muted">${esc(spec.boundary)}</p><details class="collection-evidence" open><summary>来源与采集范围</summary><div class="analysis-fields">${meta('market','国家站点 / 调研地区')}${meta('language','原文语言（如 en / ru / ja）')}${meta('source_url','来源链接')}${meta('captured_at','实际采集时间（如 2026-11-10T14:00:00Z）')}</div>${meta('raw_excerpt','支持结论的原文摘录 / 页面文本',true)}${meta('evidence_note','截图、原始文件或采集批次索引（如有）',true)}${r.platform==='research'?'':`<div class="analysis-fields">${meta('category_rules_url','该站点 / 类目的当前规则链接')}<label class="review-check"><input type="checkbox" data-collection-meta="category_rules_checked" ${r.category_rules_checked?'checked':''}>已核对实际类目的必填属性，补充在“属性、材质与规格”中</label></div>`}</details><div class="collection-fields">${spec.fields.map(f=>{const v=r.fields[f.key]||{};return `<details class="collection-field" ${f.required||v.original?'open':''}><summary>${esc(f.label)} ${badge(f.required?'采集重点':'补充资料',f.required?'blue':'gray')}</summary><div class="bilingual-fields"><label class="field"><span>原文 / 原值</span><textarea rows="3" data-collection-field="${f.key}" data-part="original">${esc(v.original)}</textarea></label>${f.translatable?`<label class="field"><span>中文翻译</span><textarea rows="3" data-collection-field="${f.key}" data-part="zh">${esc(v.zh)}</textarea></label>`:'<p class="muted">数字、链接和标识保留原值，不自动换算。</p>'}</div><div class="analysis-fields"><label class="field"><span>原文位置 / 证据索引</span><input data-collection-field="${f.key}" data-part="locator" value="${esc(v.locator)}" placeholder="例如：商品页规格区，第 3 段"></label><label class="field"><span>字段来源链接（留空沿用上方来源）</span><input data-collection-field="${f.key}" data-part="source_url" value="${esc(v.source_url)}"></label><label class="field"><span>内容性质</span><select data-collection-field="${f.key}" data-part="kind">${[['source_statement','来源中的陈述'],['inference','推算 / 个人判断'],['conflict','来源冲突'],['unverified','待核实']].map(([key,label])=>`<option value="${key}" ${v.kind===key?'selected':''}>${label}</option>`).join('')}</select></label>${f.translatable?`<label class="review-check"><input type="checkbox" data-collection-field="${f.key}" data-part="reviewed" ${v.reviewed?'checked':''}>已对照原文校对中文与关键数据</label>`:''}</div>${v.translation?`<p class="muted">${v.translation.edited_by_user?'模型译文经手动修改，初始模型：':'模型译文来源：'}${esc(v.translation.model)} · ${esc(v.translation.translated_at)} · 任务 ${esc(v.translation.job_id)}${v.translation.warnings?.length?' · '+esc(v.translation.warnings.join('；')):''}</p>`:''}</details>`}).join('')}</div><div class="form-actions"><button class="primary" data-action="collection-translate" ${collection.translation?'disabled':''}>${collection.translation?'翻译进行中…':'自动翻译待译字段'}</button><button data-action="collection-check">检查完整性与译文</button><button data-action="collection-export">导出草稿与证据</button><button data-action="collection-final">导出经审阅资料</button></div><p class="muted" id="translation-status" role="status">${collection.translation?'翻译任务 '+esc(collection.translation.id)+' 已提交；可继续编辑，返回时只填入未改动的字段。':'翻译使用本机私有配置选择的模型，仅发送有原文且中文为空的字段；不会改写原文。'}</p><div id="collection-feedback" aria-live="polite">${collectionFeedback()}</div>${spec.references.length?`<details class="knowledge-directory"><summary>平台参考资料与模板边界</summary><ul>${spec.references.map(x=>`<li><a href="${esc(x.url)}" target="_blank" rel="noreferrer noopener">${esc(x.title)}</a> · 核对日期 ${esc(x.checked_on)}</li>`).join('')}</ul><p class="muted" data-ui-help>模板不包含各类目的实时全量属性；请在实际站点核对。</p></details>`:''}<p class="muted" data-ui-help>未保存的参数仅保留在当前面板。可显式保存到本机并恢复；导出会下载 CSV 和含原文、哈希的 JSON 证据包，也可重新导入 JSON。哈希用于核对内容变化，不能证明网页或陈述真实。</p>`}</section>`;
  }
  function editCollection(element){
    if(!collection.record||collection.loading)return;
    const value=element.type==='checkbox'?element.checked:element.value;
    if(element.dataset.collectionMeta)collection.record[element.dataset.collectionMeta]=value;
    else if(element.dataset.collectionField){const field=collection.record.fields[element.dataset.collectionField];field[element.dataset.part]=value;if(element.dataset.part==='original'||element.dataset.part==='zh'){field.reviewed=false;const check=document.querySelector(`[data-collection-field="${element.dataset.collectionField}"][data-part="reviewed"]`);if(check)check.checked=false;if(element.dataset.part==='original')delete field.translation;else if(field.translation)field.translation.edited_by_user=true}}
    collection.revision++;collection.check=null;collection.error='';renderCollectionFeedback();
  }
  async function checkCollection(){const revision=collection.revision;const checked=await organization.produce('commerce_collection_check',{record:collection.record});if(revision===collection.revision){collection.check=checked;collection.error='';renderCollectionFeedback()}return checked}
  async function exportCollection(final){
    const record=structuredClone(collection.record),revision=collection.revision;
    const checked=await checkCollection();if(final&&checked.issues.length){toast('仍有缺项或待校对内容，请查看检查结果');return}
    const result=await organization.produce('commerce_collection_export',{record,final});if(revision!==collection.revision){toast('资料已修改，请检查后重新导出');return}
    download(result.json,result.filename+'.json','application/json;charset=utf-8');download(result.csv,result.filename+'.csv','text/csv;charset=utf-8');toast(final?'已导出经审阅资料和证据包':'已导出草稿和证据包');
  }
  async function translateCollection(){
    if(collection.translation)return;
    const record=collection.record,items=[];let total=0;
    if(!record.language.trim())throw Error('请先填写原文语言');
    for(const field of collection.spec.fields){const value=record.fields[field.key];if(field.translatable&&value.original.trim()&&!value.zh.trim()&&total+value.original.length<=12000){items.push({id:field.key,text:value.original});total+=value.original.length}}
    if(!items.length)throw Error('没有待译原文，或单批文本过长；请分批整理后翻译');
    const input={language:record.language,items},fingerprint=JSON.stringify(input);
    if(collection.translationRequest?.fingerprint!==fingerprint)collection.translationRequest={fingerprint,key:crypto.randomUUID()};
    collection.translation={id:'正在提交',record,items};paint();
    try{
      const job=await organization.produce('commerce_translation_start',{input,idempotency_key:collection.translationRequest.key},{record:structuredClone(record)});collection.translation.id=job.id;
      const status=document.querySelector('#translation-status');if(status)status.textContent='翻译任务 '+job.id+' 进行中，返回后仍需校对。';
      let result=job;const deadline=Date.now()+120000;
      while(['queued','running'].includes(result.status)&&Date.now()<deadline){await new Promise(resolve=>setTimeout(resolve,1200));result=await api('commerce_translation_get',{job_id:job.id})}
      if(result.status==='failed')collection.translationRequest=null;
      if(result.status!=='completed')throw Error(result.result?.error||'翻译尚未完成，任务 ID：'+job.id+'。请稍后查询，勿重复提交。');
      let applied=0;
      for(const translated of result.result.translations){const field=record.fields[translated.id],source=items.find(x=>x.id===translated.id);if(field.original===source.text&&!field.zh.trim()){field.zh=translated.zh;field.reviewed=false;field.translation={job_id:job.id,model:result.result.model,provider:result.result.provider,translated_at:result.result.translated_at,original_sha256:translated.original_sha256,model_output:translated.zh,model_output_sha256:translated.zh_sha256,edited_by_user:false,prompt_version:result.result.prompt_version,warnings:translated.warnings};applied++}}
      collection.revision++;collection.check=null;toast(`已填入 ${applied} 项中文译文，均待校对。`);await organization.afterTranslation(job);
    }catch(error){collection.error='翻译未完成：'+error.message}
    finally{collection.translation=null;paint()}
  }
