  async function navigate(tab,initial=false){if(!Object.hasOwn(labels,tab)||tab===state.tab&&!initial)return;const changed=tab!==state.tab;pendingFormRestore=null;formRestoreGeneration++;business.cancelEditor?.();state.groupVisited[ui.moduleDetails(tab).group]=tab;state.focusTitle=tab!==state.tab;state.tab=tab;if(reactHost&&changed)parent.postMessage({type:'commerce:workspace-navigate',nonce:bridgeNonce,tab:tab==='operations'&&analysis.mode==='stock'?'restock':tab},'*');if(['insights','support'].includes(tab)){paint();business.enter(tab==='support'?'support':'reviews');return}if(state.tab==='pilots'){paint();pilots.enter();return}if(state.tab==='platforms'){paint();platforms.enter();return}if(state.tab==='exposure'){paint();exposure.enter();return}if(state.tab==='agent'){paint();agent.enter();return}if(state.tab==='skills'){paint();skills.enter();return}if(state.tab==='creative'){paint();creative.enter();return}if(state.tab==='intelligence'){paint();intel.enter();return}if(state.tab==='organization')await organization.load();else if(state.tab==='live')await live.load();else if(state.tab==='alerts')await Promise.all([ops.load(),live.load()]);else if(state.tab==='connections')await connectionHub.load();else if(state.tab==='research'&&!collection.spec)await openCollection(collection.platform);else paint();}
  const currentScope=()=>JSON.stringify([state.demo,state.platform,state.store,state.market,state.query]);
  let loadGeneration=0;
  async function load(){
    const generation=++loadGeneration,scope=currentScope();if(state.dataScope!==scope)state.data=null;
    state.busy=true;state.error=null;paint();
    try{
      const args={demo:state.demo,platform:state.platform,store_id:state.store,market:state.market};
      const [[data,orders,products],secondary]=await Promise.all([
        Promise.all([api('commerce_dashboard',args),api('commerce_orders_list',{...args,query:state.query}),api('commerce_products_list',args)]),
        Promise.allSettled([api('commerce_task_list'),api('commerce_reports_list'),api('commerce_status'),api('commerce_knowledge_list'),api('commerce_runtime_status')])
      ]);
      if(generation!==loadGeneration)return;
      const values=secondary.map(r=>r.status==='fulfilled'?r.value:null),labels=['共享任务','简报草稿','连接状态','业务知识','运行状态'];
      Object.assign(state,{data,dataScope:scope,loadedAt:Date.now(),orders:orders.orders,products:products.products,tasks:values[0]?.tasks||[],reports:values[1]?.reports||[],connections:values[2],notes:values[3]?.notes||[],runtime:values[4],secondaryErrors:secondary.flatMap((r,i)=>r.status==='rejected'?[labels[i]]:[]),error:null});
    }catch(e){if(generation===loadGeneration)state.error=e.message}
    finally{if(generation===loadGeneration){state.busy=false;paint()}}
  }

