  async function importCollection(file){
    if(!file)return;
    try{
      if(file.size>130000)throw Error('文件过大，请拆分为单条资料记录');
      const data=JSON.parse(await file.text()),record=data.record||data;
      await api('commerce_collection_check',{record});const spec=await api('commerce_collection_template',{platform:record.platform});
      if(collection.record)collection.drafts[collection.record.platform]=collection.record;
      for(const field of spec.fields)record.fields[field.key]={...spec.record.fields[field.key],...record.fields[field.key]};
      Object.assign(collection,{platform:record.platform,spec,record,loading:false,check:null,error:''});collection.revision++;paint();toast('已导入资料，可继续翻译与校对');
    }catch(error){collection.error='导入失败：'+error.message;renderCollectionFeedback()}
  }
